INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:1-3', 'QRTA:zamakhshari:40-01', 'zamakhshari', 1, 3, 40, 1, 3, 'The chapter is Meccan except one verse; it has eighty-five verses, or eighty-two.', '["The chapter is from Medina except one verse, which was about the prayers.", "The chapter has eighty-two verses, and it came down before الزمر."]', 'Where the chapter came down', NULL, '[]', 'The commentator says the chapter came down in Mecca. One view leaves out the verse «وسبح بحمد ربك», because the set prayers came down in Medina. Others say every chapter that opens with حم is Meccan. He counts eighty-five verses, with a second count of eighty-two, and then the بسم الله begins.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:4-4', 'QRTA:zamakhshari:40-01', 'zamakhshari', 4, 4, 40, 1, 3, 'حم is read with حا leaning or full, and م silent or with a fatha.', '["حم has only one reading: a silent م and a full, open حا.", "Here الإمالة means stretching the م, and تفخيم means dropping it."]', 'Leaning a long vowel', 'الإمالة', '["GT:phonotactic:imala"]', 'Once the بسم الله ends, the commentator lists how حم has been read. The long vowel of حا can be read with الإمالة, leaning its sound toward a kasra, or with تفخيم, the full open sound. The م can be read with no vowel (تسكين) or with a fatha (فتح). So the listener may hear حم said in more than one way.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:5-6', 'QRTA:zamakhshari:40-01', 'zamakhshari', 5, 6, 40, 1, 3, 'The fatha on م avoids two silent letters, or marks حم as object of a hidden ''Recite''.', '["The fatha on م shows حم is the subject and fully declined.", "The fatha is chosen as the heaviest vowel, as in أين and كيف."]', 'Why the م takes a fatha', NULL, '["GT:phonotactic:iltiqa_sakinayn", "GT:case:accusative", "GT:irab_role:idmar_al_amil", "GT:noun_process:man_al_sarf", "GT:gender:feminine"]', 'He gives two reasons for the fatha. First, two letters with no vowel meet (التقاء الساكنين), so one needs a vowel, and the lightest one, the fatha, is picked, just as in أين and كيف. Second, حم may be in the accusative (النصب) as the object of a hidden verb اقرأ, ''Recite حم''. It then shows only a fatha because it is barred from full declension (منع الصرف): it is feminine and definite, or definite and on a foreign pattern like قابيل and هابيل.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:7-8', 'QRTA:zamakhshari:40-01', 'zamakhshari', 7, 8, 40, 1, 3, 'التوب, الثوب and الأوب all mean returning; الطول means bounty and something extra.', '["التوب, الثوب and الأوب mean three different things: repenting, clothing and travelling.", "الطول here means length and long life, not bounty."]', 'Words that share one meaning', NULL, '[]', 'The commentator explains two words of the verse. التوب, repentance, is a ''sister'' of الثوب and الأوب: all three carry the sense of coming back. So repentance at heart is a returning. Then he explains الطول in ذي الطول: it means bounty, giving more than is due.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:9-10', 'QRTA:zamakhshari:40-01', 'zamakhshari', 9, 10, 40, 1, 3, 'People say someone has طول over another, or طال عليه and تطول, for doing favours.', '["طال عليه means the time grew long for him, as when someone waits.", "تطول means he acted proudly over someone and showed off his rank."]', 'How the word طول is used', NULL, '[]', 'He backs up the meaning of الطول with common Arabic usage. ''So-and-so has طول over so-and-so'' means he has done him favours. The verbs طال عليه and تطول are used when someone gives a favour. So ذي الطول presents God as the One who gives freely.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:11-11', 'QRTA:zamakhshari:40-01', 'zamakhshari', 11, 11, 40, 1, 3, 'Question: why are these describing words mixed definite and indefinite, when their noun is definite?', '["Question: why is the described noun indefinite, when all its describing words are definite?", "Question: why do these describing words differ in gender, when their noun is masculine?"]', 'The adjective and its noun', 'نعت', '["GT:irab_role:naat", "GT:definiteness:definite", "GT:definiteness:indefinite"]', 'The commentator raises a problem. The phrases غافر الذنب, قابل التوب, شديد العقاب and ذي الطول look like describing words (الصفات). A describing word (نعت) must match its noun in being definite (معرفة) or indefinite (نكرة). The noun they describe is definite, so they should all be definite too, yet they seem to differ.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:12-14', 'QRTA:zamakhshari:40-01', 'zamakhshari', 12, 14, 40, 1, 3, 'غافر الذنب and قابل التوب are definite: they mean lasting qualities, not one-time acts.', '["غافر الذنب and قابل التوب are indefinite because they speak of forgiving now or tomorrow.", "They are definite because they say God will forgive sins only on a future day."]', 'Lasting quality, not a timed act', NULL, '["GT:definiteness:definite", "GT:idafa_kind:lafziya"]', 'The answer: these two are definite (معرفة). A word like غافر would stay indefinite only if it meant one act happening now or tomorrow; then its link to الذنب would be a loose, surface link (الإضافة اللفظية) that does not make it definite. But the meaning here is that forgiving and accepting are fixed, lasting qualities. So they act like إله الخلق and رب العرش, which are plainly definite.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:15-16', 'QRTA:zamakhshari:40-01', 'zamakhshari', 15, 16, 40, 1, 3, 'شديد العقاب is a problem, since it means ''His punishment is severe''; الزجاج called it a substitute.', '["شديد العقاب is easy, since it simply means ''the Punisher'', a fixed definite title.", "الزجاج made شديد العقاب a describing word that matches the other phrases."]', 'The substitute (بدل)', 'بدل', '["GT:irab_role:badal"]', 'The third phrase is harder. شديد العقاب really means ''severe is His punishment'', and it can never lose that sense. So شديد only describes the punishment, and its link to العقاب cannot make it definite. To solve this, الزجاج treated it as a substitute (بدل), a word that stands in place of an earlier one, not a describing word.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:17-17', 'QRTA:zamakhshari:40-01', 'zamakhshari', 17, 17, 40, 1, 3, 'Making this one phrase alone a substitute, among describing words, is clearly out of place.', '["Making this phrase a substitute fits well, since substitutes often sit among describing words.", "Making all the phrases describing words is clearly out of place."]', 'One substitute among adjectives', 'بدل', '["GT:irab_role:badal", "GT:irab_role:naat"]', 'The commentator rejects that answer. If شديد العقاب alone is a substitute (بدل) while the phrases around it are describing words (الصفات), the chain becomes uneven. The word نبو means something jarring and out of place. A good reading should treat the whole chain the same way.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:18-21', 'QRTA:zamakhshari:40-01', 'zamakhshari', 18, 21, 40, 1, 3, 'Better view: one indefinite among definites shows all are substitutes, as one foot fixes a metre.', '["Better view: the one indefinite among definites shows all are describing words, like a poem''s metre.", "Better view: the many definites force the one indefinite phrase to count as definite."]', 'One odd item decides the whole', NULL, '["GT:definiteness:indefinite", "GT:definiteness:definite", "GT:irab_role:badal", "GT:irab_role:naat"]', 'His own answer: one indefinite word (النكرة) among definite ones (المعارف) signals that all of them are substitutes (أبدال), not describing words (أوصاف). A substitute does not need to match in definiteness, so the problem goes away. He compares it to a poem: if every foot is مستفعلن it is judged الرجز, but if one foot is متفاعلن the whole poem is الكامل. One clear sign settles the label for the whole set.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:22-22', 'QRTA:zamakhshari:40-01', 'zamakhshari', 22, 22, 40, 1, 3, 'The question again: why do these describing words differ in definiteness, when their noun is definite?', '["The question again: why are these describing words all definite, when their noun is indefinite?", "The question again: why does the described noun change from definite to indefinite?"]', 'The adjective and its noun', 'نعت', '["GT:irab_role:naat", "GT:definiteness:definite", "GT:definiteness:indefinite"]', 'A later note quotes the commentator''s question word for word. Describing words (الصفات) should match their noun, which is definite (معرفة). Yet the chain mixes definite and indefinite (تعريفا وتنكيرا). The note quotes this before weighing the answer.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:23-24', 'QRTA:zamakhshari:40-01', 'zamakhshari', 23, 24, 40, 1, 3, 'Summed-up answer: the first two are definite, being lasting qualities, so their annexation is genuine.', '["Summed-up answer: the first two point to present or future acts, so their link is only on the surface.", "Summed-up answer: the first two are indefinite, but the noun they describe makes them definite."]', 'Genuine annexation', 'الإضافة المعنوية', '["GT:definiteness:definite", "GT:idafa_kind:manawiya"]', 'The note sums up the answer. غافر الذنب and قابل التوب are definite because they name qualities that always belong to God. They are not about an act in the present or the future. So their annexation is genuine (الإضافة المعنوية), the kind that makes a word definite.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:25-26', 'QRTA:zamakhshari:40-01', 'zamakhshari', 25, 26, 40, 1, 3, 'شديد العقاب has only a surface annexation, since adjectives like شديد never get a pure one.', '["شديد العقاب has a genuine annexation, since adjectives like شديد always become definite.", "شديد العقاب is a verbal noun, so its annexation is pure and makes it definite."]', 'The adjective like a participle', 'الصفة المشبّهة', '["GT:idafa_kind:lafziya", "GT:derivation_type:sifa_mushabbaha", "GT:idafa_kind:manawiya"]', 'The note explains why شديد العقاب is different. شديد is a الصفة المشبّهة, an adjective that works like a participle. Its annexation is never pure (محضة): the link to العقاب is only on the surface (الإضافة اللفظية), so it stays indefinite. That is why it clashes with the definite phrases around it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:27-28', 'QRTA:zamakhshari:40-01', 'zamakhshari', 27, 28, 40, 1, 3, 'Back to the quote: one lone substitute among describing words is plainly out of place.', '["Back to the quote: الزجاج made every phrase a substitute, and this is plainly right.", "Back to the quote: one substitute standing among describing words is quite normal."]', 'One substitute among adjectives', 'بدل', '["GT:irab_role:badal", "GT:irab_role:naat"]', 'The note goes back to quoting the commentator. الزجاج made شديد العقاب alone a substitute (البدل). One substitute on its own among describing words (الصفات) is plainly jarring. So that reading is set aside.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:29-32', 'QRTA:zamakhshari:40-01', 'zamakhshari', 29, 32, 40, 1, 3, 'Quoted view: all are substitutes, since the indefinite cannot describe; one metre foot shows the same.', '["Quoted view: all are describing words, since the indefinite can still describe a definite noun.", "Quoted view: a single متفاعلن foot in a poem still leaves it in الرجز."]', 'One odd item decides the whole', NULL, '["GT:irab_role:badal", "GT:irab_role:naat", "GT:definiteness:indefinite"]', 'The note quotes the better view. All the phrases are substitutes (أبدال), not describing words, because the indefinite (النكرة) cannot rightly describe a definite noun. The poem example is repeated: all مستفعل feet point to الرجز, but one متفاعلن foot makes the poem الكامل. Then the quote ends and the note''s writer starts his own comment.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:33-35', 'QRTA:zamakhshari:40-01', 'zamakhshari', 33, 35, 40, 1, 3, 'One foot decides because متفاعلن can become مستفعلن in الكامل, but never the reverse in الرجز.', '["One foot decides because مستفعلن can become متفاعلن in الرجز, but never the reverse.", "Both metres stay possible, so the poem should be left without a label."]', 'Choosing what fits all the evidence', NULL, '[]', 'The note explains why the poem example works. In الكامل, the foot متفاعلن can turn into مستفعلن when its second letter loses its vowel (الإضمار). In الرجز, مستفعلن can never turn into متفاعلن. So only الكامل can hold both feet, and you must pick the label that fits all the evidence, just as a specific proof is preferred over a general one so both can stand.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:36-38', 'QRTA:zamakhshari:40-01', 'zamakhshari', 36, 38, 40, 1, 3, 'Another view: they are describing words; شديد العقاب lost its article to match its neighbours.', '["Another view: شديد العقاب gained the article so it would match its neighbours in meaning.", "Another view: they are substitutes, and the article was dropped to make the meaning stronger."]', 'Changing form to match neighbours', NULL, '["GT:irab_role:naat", "GT:balagha_maani:tarif_bil_lam"]', 'A second answer is offered. They can all be describing words (صفات), and شديد العقاب lost its الألف واللام only so its form would match the words before and after it. Arabs often bend their usual rules for this pairing (الازدواج). In the saying «ما يعرف سحادليه من عنادليه», a single thing is even made dual so it pairs with a dual next to it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:39-41', 'QRTA:zamakhshari:40-01', 'zamakhshari', 39, 41, 40, 1, 3, 'A word may count as having the article, or as lacking it, when nothing is unclear.', '["Arabs drop the article only when the described noun is unknown and confusion is likely.", "In «الجماء الغفير», the article is meant to be added, not taken away."]', 'The article held in mind', 'التعريف باللام', '["GT:balagha_maani:tarif_bil_lam"]', 'Support comes from الخليل. In «ما يحسن بالرجل مثلك أن يفعل ذلك», the word مثلك is treated as if it had الألف واللام. In «الجماء الغفير», the article is there but treated as if it were gone. This is easy because there is no risk of confusion and the described noun is known. So the missing article need not stop شديد العقاب from describing a definite noun.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:42-42', 'QRTA:zamakhshari:40-01', 'zamakhshari', 42, 42, 40, 1, 3, 'Or شديد was left indefinite on purpose, to show extreme severity and sharpen the warning.', '["Or شديد was left indefinite to soften the threat and make the punishment seem small.", "Or شديد was left indefinite because its meaning is unknown and unclear to the reader."]', 'Indefiniteness for effect', 'التنكير', '["GT:balagha_maani:tankir"]', 'A third view: the indefinite form (التنكير) was chosen on purpose. Leaving it vague points to a severity so great that nothing is worse or more bitter. This makes the warning stronger. So the odd form is not a fault but a deliberate effect.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:43-44', 'QRTA:zamakhshari:40-01', 'zamakhshari', 43, 44, 40, 1, 3, 'This same point is why one picks the substitute over the describing word.', '["This point is why one must always pick the describing word over the substitute.", "This point shows the substitute and the describing word mean exactly the same here."]', 'The substitute (بدل)', 'بدل', '["GT:irab_role:badal", "GT:irab_role:naat"]', 'He links this to the earlier view. If you read the chain as substitutes (البدل), the reason for choosing that over describing words (الوصف) is this very point. The indefinite form was meant to stress the severity. So the meaning and the grammar support each other.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:45-45', 'QRTA:zamakhshari:40-01', 'zamakhshari', 45, 45, 40, 1, 3, 'Question: what is the point of the و in «وقابل التوب»?', '["Question: why does قابل التوب come before غافر الذنب in the verse?", "Question: what is the meaning of the word التوب in «وقابل التوب»?"]', 'The joining و', 'وَاو العَطْف', '["GT:harf_maani:atf"]', 'The commentator asks about the small word و before قابل التوب. A list of God''s names could run on without ''and'', so he asks what it adds. The next lines give his answer.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:46-49', 'QRTA:zamakhshari:40-01', 'zamakhshari', 46, 49, 40, 1, 3, 'The و shows two mercies for the repentant sinner: his repentance accepted and his sin wiped out.', '["The و shows two separate groups: sinners who are forgiven, and others whose repentance is accepted.", "The و shows God accepts the repentance but still keeps the sin on record."]', 'Two mercies joined by و', NULL, '[]', 'The و joins forgiving and accepting as one gift to the same person. God accepts the repentance and writes it down as a good deed of obedience. He also makes it wipe out the sins (محاءة), as if the person never sinned. It is as if the verse said ''He who combines forgiveness and acceptance''.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:50-51', 'QRTA:zamakhshari:40-01', 'zamakhshari', 50, 51, 40, 1, 3, 'عمر missed a brave man from Syria and was told he had given himself over to drink.', '["عمر missed a brave man and was told he had been killed in battle in Syria.", "عمر was told the man had given up drinking and gone back to his people."]', 'A story that shows the verse at work', NULL, '[]', 'Now the commentator tells a story to show the verse at work. عمر noticed that a strong, brave man from Syria was missing. He was told the man had fallen into drinking; تتابع means he kept at it, again and again. So عمر called his scribe.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:52-55', 'QRTA:zamakhshari:40-01', 'zamakhshari', 52, 55, 40, 1, 3, 'The letter of عمر gives greetings and praise, then simply quotes the opening of this chapter.', '["The letter of عمر scolds the man at length and threatens him with punishment.", "The letter of عمر quotes the whole chapter from its start to its end."]', 'Letting the verse speak', NULL, '[]', 'The letter is short. After the greeting and praise of God, it simply quotes بسم الله and then حم up to «إليه المصير». So the whole message of the letter is these verses: God forgives sin, accepts repentance, and is severe in punishment.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:56-57', 'QRTA:zamakhshari:40-01', 'zamakhshari', 56, 57, 40, 1, 3, 'عمر sealed it, said to deliver it only when the man was sober, and had others pray.', '["عمر told the messenger to hand it over at once, whether the man was drunk or sober.", "عمر told the people with him to pray against the man because of his sin."]', 'Care in giving advice', NULL, '[]', 'عمر took care over how the letter reached the man. It was to be handed over only when he was sober (صاحيا), so he could take it in. He also asked the people with him to pray that the man would repent. The advice came with prayer, not words alone.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:58-60', 'QRTA:zamakhshari:40-01', 'zamakhshari', 58, 60, 40, 1, 3, 'Reading it, the man saw both the promise and the warning, wept, and truly gave up drinking.', '["Reading it, the man felt only threatened, and kept on drinking for a while.", "Reading it, the man thought God had promised to forgive him whatever he did."]', 'Hope and fear together', NULL, '[]', 'The man read the letter again and again. He said: God has promised to forgive me and has warned me of His punishment. These two sides of the verse moved him to tears. He then stopped, and stopped well, and his repentance was sound; then the news reached عمر.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:61-62', 'QRTA:zamakhshari:40-01', 'zamakhshari', 61, 62, 40, 1, 3, 'The lesson of عمر: help a brother who slips, pray for him, never side with the devils.', '["The lesson of عمر: cut off a brother who slips until he repents on his own.", "The lesson of عمر: report a brother who slips so that others can warn him."]', 'How to treat a brother who slips', NULL, '[]', 'عمر draws the lesson for everyone. When a brother slips (زل زلة), set him straight (سددوه) and support him (وقفوه). Pray that God turns to him in forgiveness. Do not become helpers of the devils against him. Then a note on the story''s sources begins.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:zamakhshari:40-01:63-65', 'QRTA:zamakhshari:40-01', 'zamakhshari', 63, 65, 40, 1, 3, 'The source note says one book records the story in full, another in short form.', '["The source note says the story is recorded only in short form in every book.", "The source note says the story has no source and was never written down."]', 'Full and shortened reports', NULL, '[]', 'This note says where the story is written down. One report gives it in full (بتمامه), with the words «فذكره بتمامه». Another gives it in short form (باختصار). Others record it as well.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:1-2', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 1, 2, 40, 1, 3, 'Like other opening letters, حم comes before mention of the Qur’an and challenges deniers to match it.', '["حم is unlike the other opening letters, so it needs its own separate explanation.", "The opening letters are a warning that the deniers will be punished for their denial."]', 'Separate letters at surah openings', 'حُرُوف مُقَطَّعَة', '["GT:harf_maani:muqattaa"]', 'The writer says حم is explained the same way as the other separate letters (الحروف المقطعة) that open many surahs. Most of these letters are followed by mention of the Qur’an. That points to a challenge: the deniers cannot produce anything to rival it. So حم is not a stray sound; it opens the talk about the Book.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:3-5', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 3, 5, 40, 1, 3, 'Letter names like حا, را, يا are said short at surah openings, dropping the hamza in pause.', '["Letter names like حا are said long, keeping the hamza, to stress each letter.", "The hamza is dropped because these names join the next word, not because of a pause."]', 'Shortened names of letters', 'المقصور والممدود', '["GT:noun_process:maqsur_mamdud", "GT:phonotactic:takhfif_hamza", "GT:phonotactic:waqf"]', 'Some letter names normally end in a long vowel plus a hamza (ممدودة الآخر). At the openings of surahs they are said short (مقصورة): the hamza is dropped to make them lighter. This happens because each letter is said in a state of pause (الوقف). Examples are حا in حم, را in الر, and يا in يس.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:6-6', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 6, 6, 40, 1, 3, 'The verse on sending down the Book is explained just as at the opening of سورة الزمر.', '["This verse is explained differently from the opening of سورة الزمر, which it contradicts.", "The Book sent down here means only سورة الزمر, not the whole Qur’an."]', 'Same opening as another surah', NULL, '[]', 'The second verse, تنزيل الكتاب من الله العزيز العليم, opens almost like سورة الزمر. So the writer says its explanation is the same as the one given there. He then adds only what is new here.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:7-7', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 7, 7, 40, 1, 3, 'This statement is aimed at the polytheists who deny that the Qur’an is sent down from God.', '["This statement is aimed at the believers, to make their faith in the Qur’an stronger.", "The polytheists accept the Qur’an is from God but deny that it was sent down."]', 'Who the statement is aimed at', NULL, '["GT:balagha_maani:khabar"]', 'The extra point here is about who the statement (الخبر) is for. It is directed at the polytheists who deny that the Qur’an comes down from God. Knowing the audience explains how the sentence is built, as the next sentence shows.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:8-9', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 8, 9, 40, 1, 3, 'No emphasis is used, treating deniers as non-deniers, since the proofs around them should end their denial.', '["No emphasis is used because the deniers were few and their denial did not matter.", "Emphasis is added because the deniers reject the Qur’an strongly and must be convinced."]', 'Treating a denier as a non-denier', 'تنزيل المنكر منزلة غير المنكر', '["GT:balagha_maani:khabar", "GT:balagha_maani:mukhalafat_muqtada_zahir", "GT:balagha_maani:tanzil_al_munkir_manzilat_ghayr_al_munkir"]', 'When you tell a denier something, you would expect emphasis words (المؤكد). Here the statement comes plain, with no emphasis. This goes against what the situation seems to need (خلاف مقتضى الظاهر): the denier is treated as if he did not deny. The reason is that he is surrounded by proofs that would stop his denial if he thought about them, so he had no right to deny.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:10-11', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 10, 11, 40, 1, 3, 'Six definite epithets follow God''s name: some definite with ال, some by annexation to a definite noun.', '["Six indefinite epithets follow God''s name, so they describe Him only loosely.", "The epithets are definite because each one is a proper name of God."]', 'Definite epithets after God''s name', 'نعت', '["GT:irab_role:naat", "GT:definiteness:definite", "GT:balagha_maani:tarif_bil_lam", "GT:balagha_maani:tarif_bil_idafa"]', 'The verses give six descriptions after the name الله. Each is an epithet (نعت), and all are definite (معارف). Some are definite through ال, like العزيز and العليم. Others are definite through annexation (الإضافة) to a noun that has ال, like غافر الذنب.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:12-14', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 12, 14, 40, 1, 3, '''Almighty, All-Knowing'' hints deniers are overpowered, known by God, and cannot produce anything like the Qur’an.', '["''Almighty, All-Knowing'' simply praises God and says nothing about the deniers.", "''All-Knowing'' means God knows the deniers will one day believe in the Qur’an."]', 'Hidden message in two attributes', 'التعريض', '["GT:balagha_bayan:tarid", "GT:balagha_bayan:kinaya_ramziyya"]', 'Calling God العزيز العليم here carries an indirect message (تعريض) to those who deny the Book was sent down. العزيز hints that they are beaten and overpowered. العليم hints that God knows what they hide and will hold them to account. It is also a quiet hint (رمز) that the Qur’an is the speech of the Mighty and Knowing, so no one but God can make anything like it, or even knows how.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:15-16', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 15, 16, 40, 1, 3, 'This explains why this verse has العليم where سورة الزمر has الحكيم, though the two overlap.', '["This verse has الحكيم like سورة الزمر, and both carry exactly the same message.", "العليم here cancels the readings that الحكيم allowed in سورة الزمر."]', 'Why similar verses end differently', NULL, '[]', 'The opening of سورة الزمر has العزيز الحكيم, while this verse has العزيز العليم. The writer says the hints just explained are the reason for this difference. Still, the description by knowledge can also carry some of the meanings that الحكيم carried there.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:17-17', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 17, 17, 40, 1, 3, 'Both attributes here also point, as in سورة الزمر, to the Qur’an being impossible to imitate.', '["The two attributes here reject the point about the Qur’an''s uniqueness made in سورة الزمر.", "Only الحكيم in سورة الزمر shows the Qur’an cannot be matched; the attributes here do not."]', 'The Qur’an cannot be matched', NULL, '[]', 'As in سورة الزمر, the two attributes العزيز and العليم can also be read as pointing to the إعجاز of the Qur’an: no one can match it. So the link between these attributes and the Qur’an''s uniqueness holds in both places.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:18-19', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 18, 19, 40, 1, 3, 'The two attributes hint that God chooses His messenger, not the great men people put forward.', '["The attributes hint that God chose a great man from the two towns, as people wished.", "The attributes hint that people may choose whom God sends with His message."]', 'Who receives God''s message', 'الكناية الرمزية', '["GT:balagha_bayan:kinaya_ramziyya"]', 'Mentioning العزيز العليم is also a hint (رمز) that God knows best where to place His message. He does not follow people''s wishes about which of their great men should receive it. The writer ties this to the deniers'' words: ''Why was this Qur’an not sent down to a great man from the two towns?''', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:20-22', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 20, 22, 40, 1, 3, 'The forgiveness attributes strengthen the hint: deniers can still repent and be forgiven, like past nations.', '["The forgiveness attributes cancel the earlier warning, so the deniers face no threat.", "The forgiveness attributes mean past nations were forgiven, but these deniers cannot be."]', 'Strengthening an indirect hint', NULL, '["GT:balagha_bayan:tarid"]', 'After the two great attributes come غافر الذنب, قابل التوب, شديد العقاب, ذي الطول. These strengthen (ترشيح) the earlier indirect message (التعريض). It is as if God says: if you sinned by rejecting the Qur’an, fixing it is still in your hands, because God is known for accepting repentance and forgiving sin. Just as He forgave past nations who repented, He will forgive any of you who repents.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:23-24', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 23, 24, 40, 1, 3, '''Forgiver'' comes before ''Accepter of repentance'' to announce forgiveness quickly; the pairs give hope and warning.', '["''Forgiver'' comes first because forgiveness happens before repentance is accepted.", "Both pairs of attributes are meant only to warn the deniers, not to give them hope."]', 'Putting ''Forgiver'' first', 'التقديم والتأخير', '["GT:balagha_maani:taqdim_takhir", "GT:balagha_bayan:tarid"]', 'In reality, forgiveness comes after repentance is accepted. Yet غافر is placed first (تقديم), out of care to tell anyone ready to fix his state, without delay, that forgiveness is there. So غافر الذنب وقابل التوب carry a hidden call of hope (الترغيب). And شديد العقاب ذي الطول carry a hidden warning (الترهيب).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:25-25', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 25, 25, 40, 1, 3, 'التوب is the verbal noun of تاب; التوب, الثوب and الأوب all mean returning to God''s command.', '["التوب is the plural of توبة, and it means regret rather than returning.", "التوب means returning, but الثوب here means a garment, so the two differ."]', 'The verbal noun التوب and its meaning', 'مَصْدَر', '["GT:derivation_type:masdar"]', 'التوب is the verbal noun (المصدر) of تاب, ''he repented''. Three words share one meaning: التوب with ت, الثوب with ث, and الأوب. All mean returning. Here it is returning to God''s command and obeying it after moving away from it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:26-29', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 26, 29, 40, 1, 3, '''And'' joins two attributes to show God gives the repentant two mercies: accepting repentance and erasing sins.', '["''And'' joins the attributes to show that forgiving and accepting repentance are for two different groups.", "The attributes are joined to show God accepts repentance but still keeps the sins on record."]', 'Why ''and'' joins two attributes', 'عطف', '["GT:irab_role:atf", "GT:balagha_maani:fasl"]', 'Most attributes here follow one another with no ''and'' (الفصل), like العليم غافر الذنب and شديد العقاب. But قابل التوب is joined to غافر الذنب with ''and'' (عطف). This points to a fine point: the repentant sinner gets two mercies together. God accepts his repentance and counts it as obedience, and He erases the sins he regretted, as if he never did them. This is a favour from God.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:30-31', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 30, 31, 40, 1, 3, '''Severe in punishment'' openly threatens Qur’an deniers, as it follows the verse on its sending down.', '["''Severe in punishment'' threatens all sinners in general, with no link to the Qur’an.", "''Severe in punishment'' is only a hidden hint, not an open threat to the deniers."]', 'An open threat to deniers', NULL, '[]', 'شديد العقاب states the threat plainly, and it is aimed at those who deny the Qur’an. We know this from where it stands: right after ''The sending down of the Book is from God''. The order of the words carries this extra meaning (مستتبعات التراكيب), even though the deniers are not named.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:32-34', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 32, 34, 40, 1, 3, '''Forgiver'' and ''Accepter'' describe what God already is, not future acts, so annexation makes them definite.', '["''Forgiver'' and ''Accepter'' mean God will forgive and accept later, acting like verbs.", "Because they act like verbs, ''Forgiver'' and ''Accepter'' stay indefinite despite the annexation."]', 'Active participle as a fixed quality', 'اسم الفاعل', '["GT:derivation_type:active_participle", "GT:balagha_maani:tarif_bil_idafa"]', 'غافر and قابل do not mean ''He will forgive'' or ''He will accept''. They mean God is already known for these qualities. So the active participle (اسم الفاعل) here no longer behaves like a verb and does not govern as a verb does. Because of that, annexation can make it definite (التعريف بالإضافة), which brings it closer to a plain noun. The writer says only this reading fits here.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:35-36', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 35, 36, 40, 1, 3, 'شديد is annexed to its agent; the definite العقاب lets it describe the definite name الله.', '["شديد is an active participle that takes العقاب as its object, like a verb.", "شديد stays indefinite, so it cannot be an epithet of God''s name here."]', 'How شديد can describe الله', 'الصفة المشبّهة', '["GT:derivation_type:sifa_mushabbaha", "GT:irab_role:fail", "GT:irab_role:naat", "GT:definiteness:definite"]', 'شديد is an adjective that resembles a participle (الصفة المشبهة). It is annexed to its agent (الفاعل): the meaning is ''whose punishment is severe''. It is an epithet (نعت) of الله, which is definite. This works because the ال on العقاب stands in for the adjective''s own definiteness. So the usual rule holds: the epithet and the word it describes match in definiteness.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:37-39', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 37, 39, 40, 1, 3, 'Grammarians differ on whether this adjective gains definiteness by annexation; the writer calls it minor.', '["All grammarians agree this adjective becomes definite by annexation, so there is no dispute.", "This kind of adjective cannot be annexed at all, since it has no agent."]', 'Can annexation make it definite?', 'التعريف بالإضافة', '["GT:balagha_maani:tarif_bil_idafa", "GT:derivation_type:sifa_mushabbaha", "GT:irab_role:fail"]', 'Some grammarians say the الصفة المشبهة becomes definite through annexation, like other annexed words. Others allow this for other adjectives but not for this one. Their reason: it is annexed to what is really its agent (فاعل), so the annexation only shortens the wording (تخفيف لفظي) and adds no definiteness. The writer ends by saying the matter is small.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:40-44', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 40, 44, 40, 1, 3, 'الطول means wide bounty or power; with ''severe in punishment'' it warns of punishment in both worlds.', '["الطول here means length of life, so it promises the deniers a long delay.", "''Possessor of power'' warns of the next life, and ''severe in punishment'' of this world."]', 'Meanings of الطول', NULL, '[]', 'الطول can mean wide bounty, great wealth, or power, and a dictionary takes the meaning of power for this verse. Paired with شديد العقاب, and set against غافر الذنب وقابل التوب, it warns of two punishments. شديد العقاب points to punishment in the next life, and ذي الطول to punishment in this world. Verses about God''s power over the deniers, like ''We have full power over them'', support this.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:45-45', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 45, 45, 40, 1, 3, 'Next come God''s oneness and the return to Him, condemning الشرك and refuting denial of resurrection.', '["Oneness and the return are mentioned to comfort believers, not to answer the polytheists.", "Oneness is mentioned to prove the resurrection, and the return to refute الشرك."]', 'A clear verdict against الشرك', 'التسجيل', '["GT:balagha_maani:tasjil"]', 'After the attributes, the verse adds ''There is no god but He'' and ''to Him is the final return'' (المصير, the place of return). These record a clear verdict (تسجيل) that taking partners besides God is false. They also break the polytheists'' claim that being raised after death is impossible.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:46-48', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 46, 48, 40, 1, 3, '''No god but He'' acts as an attribute; ''to Him is the return'' warns of reward or punishment.', '["''There is no god but He'' is a separate new sentence, not linked to God''s name.", "''To Him is the return'' promises only reward, since the attributes before it gave hope."]', 'A sentence acting as an attribute', 'نعت (صفة)', '["GT:sentence_class:jumla", "GT:sentence_role:naat"]', 'The sentence (جملة) لا إله إلا هو stands in the place of an attribute (صفة) describing God. Then إليه المصير warns of resurrection and recompense. The attributes before it raised both hope and fear, so the listeners should know the end is either His reward or His punishment. Let them weigh themselves and see where they stand.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:49-51', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 49, 51, 40, 1, 3, 'إليه comes first for emphasis and to keep the verse endings: a soft letter then a sound letter.', '["إليه is put first only for the rhyme, with no added meaning or emphasis.", "The verse endings share two soft letters, so المصير had to come last."]', 'Fronting to keep the verse pattern', 'رِعَايَة الفَاصِلَة', '["GT:balagha_maani:taqdim_takhir", "GT:irab_role:jarr_majrur", "GT:balagha_badi:riayat_fasila"]', 'In إليه المصير, the prepositional phrase (المجرور) إليه comes before المصير. There are two reasons: care for it (الاهتمام), and keeping the pattern of the verse endings (رعاية الفاصلة). The endings here share two letters: a soft letter (حرف لين) followed by a sound letter (حرف صحيح), as in العليم, البلاد and عقاب.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:52-54', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 'ibn_ashur', 52, 54, 40, 1, 3, 'The surah''s opening sums up its aims and warns the proud deniers, making it an excellent opening.', '["The opening only introduces the Qur’an and leaves the surah''s main aims for later.", "The opening says the polytheists'' strength and standing will last, unlike past nations."]', 'An opening that sums up the surah', 'براعة الاستهلال', '["GT:balagha_badi:baraat_istihlal"]', 'The writer looks back at the whole opening. It points to the main aims of the surah and fits the talk about the polytheists denying the Qur’an. It also hints that their pride in their strength and standing will vanish, as it did for stronger nations before them. So it does all that a fine opening should, which is called براعة المطلع or براعة الاستهلال.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:1-4', 'QRTA:razi:40-01', 'razi', 1, 4, 40, 1, 3, 'Surah غافر has eighty-five verses, revealed in Mecca; its opening verses are quoted.', '["Surah غافر has fifty-eight verses, and it was revealed in Medina.", "Surah غافر has eighty verses, and only five of them are Meccan."]', 'Surah heading and verses', NULL, '[]', 'This is the heading. The surah is called غافر, ''the Forgiver''. It has eighty-five verses (ثمانون وخمس) and is Meccan (مكية). Then verses one to six are quoted, the passage this commentary explains.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:5-8', 'QRTA:razi:40-01', 'razi', 5, 8, 40, 1, 3, 'The verses are read again, then he says this verse holds several questions.', '["The verses are read again, then he says this verse holds one hard question.", "The verses are read again, then he says their questions were settled earlier."]', 'Setting out the questions', NULL, '[]', 'The same verses are read again after the بسملة. Then he says: know that this verse holds several questions (مسائل). Each المسألة is one point to discuss, and he numbers them one by one.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:9-10', 'QRTA:razi:40-01', 'razi', 9, 10, 40, 1, 3, 'Some readers say ح of حم with i, others with a, and some in between.', '["All readers agree to say ح of حم with a full a sound.", "Some readers say م of حم with i, others with a, and some in between."]', 'Leaning the a toward i', 'الإمالة', '["GT:phonotactic:imala"]', 'This is about how the letter ح in حم is said. Some readers give it an i sound (الكسر), the rest an a sound (الفتح). A few read it in between, so the a is not fully open. This middle sound is called الإمالة: leaning the a toward i.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:11-12', 'QRTA:razi:40-01', 'razi', 11, 12, 40, 1, 3, 'The a on م comes from two vowelless letters meeting, or from a hidden verb ''recite''.', '["The a on م is the heaviest vowel, chosen to give the name more weight.", "The a on م shows حم is the subject of a hidden verb ''recite''."]', 'Two vowelless letters meeting', 'التقاء الساكنين', '["GT:phonotactic:iltiqa_sakinayn", "GT:case:accusative", "GT:irab_role:idmar_al_amil", "GT:noun_process:man_al_sarf", "GT:gender:feminine", "GT:definiteness:definite"]', 'The letter م in حم is read with a or with no vowel. One reason for the a: two vowelless letters meet, so one must take a vowel, and a is the lightest, as in أين and كيف. Or حم is the object of a hidden verb ''recite'' (اقرأ), so it is in النصب. It also takes no full endings (منع الصرف), because as a surah name it is feminine and definite.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:13-13', 'QRTA:razi:40-01', 'razi', 13, 13, 40, 1, 3, 'The no-vowel reading of م is because letter names are said with a paused ending.', '["The no-vowel reading of م is because حم is a foreign word like قابيل.", "The no-vowel reading of م is because the next word starts with a vowel."]', 'Letter names said in pause', 'الوقف', '["GT:irab_sign:sukun", "GT:phonotactic:waqf"]', 'First the line finishes the last point: حم may be treated like a foreign name on the pattern of قابيل and هابيل. Then it explains the reading with no vowel (السكون). Letter names like these are said with their endings stopped, in pause (الوقف), so no ending vowel is needed.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:14-14', 'QRTA:razi:40-01', 'razi', 14, 14, 40, 1, 3, 'The full talk on the opening letters is in سورة البقرة; here he gives the likeliest view.', '["The full talk on the opening letters is here; سورة البقرة gives only a short view.", "The opening letters are never explained elsewhere, so the full talk starts here."]', 'Opening letters of surahs', 'حُرُوف مُقَطَّعَة', '["GT:harf_maani:muqattaa"]', 'The second question is about the opening letters (الفواتح) such as حم. He says he discussed them fully at the start of سورة البقرة. Here he only gives the view he finds most likely, which comes next.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:15-17', 'QRTA:razi:40-01', 'razi', 15, 17, 40, 1, 3, 'حم names the surah; it is the subject, and ''revelation of the Book'' is its predicate.', '["حم is the predicate, and ''revelation of the Book'' is its subject.", "حم names the Book itself, and ''from God'' alone is its predicate."]', 'حم as subject of the sentence', 'مبتدأ', '["GT:irab_role:mubtada", "GT:irab_role:khabar", "GT:irab_role:taqdir"]', 'He takes حم as the name of this surah. Then حم is the subject (مبتدأ) and ''the revelation of the Book from God'' is the predicate (خبر). The underlying sense (التقدير) is: this surah, named حم, is the revelation of the Book. So the opening forms a full sentence.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:18-18', 'QRTA:razi:40-01', 'razi', 18, 18, 40, 1, 3, 'تنزيل is a verbal noun, but here it means the thing that was sent down.', '["تنزيل is a verbal noun meaning only the act of sending, not the Book.", "تنزيل is a plural meaning many things sent down over time."]', 'Verbal noun meaning the result', 'مَصْدَر', '["GT:derivation_type:masdar"]', 'تنزيل is a verbal noun (المصدر): it names the act of sending down. But here it stands for the result, the thing sent down (المنزل). So the surah is called the revealed Book itself, not the act of revealing.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:19-19', 'QRTA:razi:40-01', 'razi', 19, 19, 40, 1, 3, 'Once حم is called the revealed Book, the verse must say who sent it down.', '["Once حم is called the revealed Book, the verse must say to whom it was sent.", "Once the sender is named, the verse must say what the Book is about."]', 'Why ''from God'' follows', NULL, '[]', 'Now he turns to the words ''from God'' (من الله). Once the verse said this surah is the revealed Book, the next question is: who sent it down? ''From God'' answers that question.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:20-21', 'QRTA:razi:40-01', 'razi', 20, 21, 40, 1, 3, 'Names of majesty are added to make the listener serious and not careless.', '["Names of majesty are added to frighten the listener into not listening.", "Names of majesty are added so the listener can relax and take it lightly."]', 'Majestic names stir earnest listening', NULL, '[]', 'After ''from God'', the verse describes God with names of majesty and greatness: العزيز and العليم. The aim is to push the listener to ''roll up the sleeves'' (التشمير عن ساق الجد), that is, to listen with full effort. It also holds him back from being careless or slow (التهاون والتواني) with it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:22-24', 'QRTA:razi:40-01', 'razi', 22, 24, 40, 1, 3, 'Many say knowing God starts with knowing He is powerful, then that He knows.', '["Many say knowing God starts with knowing He knows all, then that He is powerful.", "Many say knowing God cannot be reached, which is why people differ on it."]', 'First steps in knowing God', NULL, '[]', 'People differed over what knowing God really is. A large group said: first you know that He is powerful (قادر), and after that that He knows (عالم). He sets this up because the next two names, العزيز and العليم, are about power and knowledge.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:25-26', 'QRTA:razi:40-01', 'razi', 25, 26, 40, 1, 3, 'العزيز has two meanings; the first is ''overpowering'', the One no one equals in power.', '["العزيز has two meanings; the first is ''dear'', the One loved above all.", "العزيز has two meanings; the first is ''honoured'', the One all people respect."]', 'Two senses of العزيز', NULL, '[]', 'The name العزيز can be read in two ways. The first is الغالب, ''the one who overpowers''. On this view it means the Powerful One whom no one equals in power.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:27-29', 'QRTA:razi:40-01', 'razi', 27, 29, 40, 1, 3, 'Here العزيز means ''without equal'', since the name الله already shows He is powerful.', '["Here العزيز means ''powerful'', since the name الله already shows He has no equal.", "Here العزيز carries both meanings at once, since الله shows both."]', 'Choosing the right sense', NULL, '[]', 'The second meaning of العزيز is ''the one who has no like'' (لا مثل له). He says ''powerful'' cannot be meant here. The name الله already shows that He is powerful, so العزيز must add something new: nothing is like Him.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:30-31', 'QRTA:razi:40-01', 'razi', 30, 31, 40, 1, 3, 'What has no equal cannot be a body, so He is free of desire, dislike and need.', '["What has no equal is a unique body, so He is free of desire and need.", "What has no equal cannot be a body, yet He still has desire and need."]', 'From no equal to no need', NULL, '[]', 'He follows the meaning ''no like'' step by step. Whatever has no like cannot be a body (جسم). What is not a body is free of desire and dislike (الشهوة والنفرة). And what is free of these is free of any need (الحاجة).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:32-32', 'QRTA:razi:40-01', 'razi', 32, 32, 40, 1, 3, 'العليم is an intensive form, and it is only complete if He knows everything knowable.', '["العليم is an intensive form meaning He knows a great deal, but not everything.", "العليم is a plain form meaning simply one who knows some things."]', 'Intensive form of a word', 'صيغة المبالغة', '["GT:derivation_type:mubalagha"]', 'العليم is on an intensive pattern (صيغة المبالغة): it stresses the quality of knowing. Full intensity only comes true if God knows every single thing that can be known. So the word itself points to complete knowledge.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:33-34', 'QRTA:razi:40-01', 'razi', 33, 34, 40, 1, 3, 'The phrase means the Book comes from One fully powerful, needing nothing, knowing all.', '["The phrase means the Book comes from One who needs it to bring Him benefit.", "The phrase means the Book itself is powerful and knowing, like its sender."]', 'Power, self-sufficiency and knowledge', NULL, '[]', '''From God, the Almighty, the All-Knowing'' comes down to this: the Book is sent by One fully powerful, fully free of need (الغني), and fully knowing. Such a One knows what brings good and what brings harm (المصالح والمفاسد). And He knows He has no need to gain good or push away harm for Himself.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:35-37', 'QRTA:razi:40-01', 'razi', 35, 37, 40, 1, 3, 'So His acts are wise and right, which proves this revelation is true and right.', '["So His acts are wise and right, but the revelation still needs other proof.", "So the three names show His power over people, not that the revelation is true."]', 'Why three names follow تنزيل', NULL, '[]', 'One who knows all and needs nothing is merciful and generous, and His acts are wise and right, free of anything ugly or false. That is why these three names come right after تنزيل. They show His acts are wise, so this revelation must be true and right. The line ends with وقيل, which opens a second view.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:38-39', 'QRTA:razi:40-01', 'razi', 38, 39, 40, 1, 3, 'First benefit: by His power and knowledge He sent the Quran full of good and unmatched.', '["First benefit: by His power and knowledge He made the Quran easy to imitate.", "First benefit: by people''s power and knowledge the Quran was kept in good form."]', 'Why mention power and knowledge', NULL, '[]', 'A second view says naming العزيز العليم brings two benefits. The first: God sent the Quran down in this exact form by His power and knowledge. This form holds what is good for people (المصالح) and cannot be matched (الإعجاز). Without His power and knowledge, this would not be possible.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:40-41', 'QRTA:razi:40-01', 'razi', 40, 41, 40, 1, 3, 'Second benefit: keeping the Quran safe till duties end needs unbeatable power and full knowledge.', '["Second benefit: keeping the Quran safe till duties end is left to people''s care.", "Second benefit: the Quran stays clear only for a while, then its duties end."]', 'Guarding the Quran', NULL, '[]', 'The second benefit: God took it on Himself to keep the Quran safe, to make its duties apply to all, and to keep it clear until duties end. This works only if He is mighty and never beaten, and knowing so nothing is hidden from Him. Then He describes Himself with names that join promise and threat, warning (الترهيب) and hope (الترغيب).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:42-43', 'QRTA:razi:40-01', 'razi', 42, 43, 40, 1, 3, 'The names in this verse are six kinds of attributes; he begins with the first.', '["The names in this verse are one attribute said six ways for stress.", "The verse lists three attributes, each one said twice for stress."]', 'Six attributes in one verse', NULL, '[]', 'He quotes the verse: Forgiver of sin, Accepter of repentance, Severe in punishment, Possessor of bounty, no god but He, to Him is the return. He counts these as six kinds of attributes (صفات). Then he takes them one by one, starting with the first.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:44-45', 'QRTA:razi:40-01', 'razi', 44, 45, 40, 1, 3, 'One view: He forgives a sin once forgiveness is earned, by repentance or greater obedience.', '["One view: He forgives every sin, whether or not forgiveness is earned.", "One view: He forgives a sin once the sinner pays with a greater punishment."]', 'Forgiveness that is earned', NULL, '[]', 'The first attribute is غافر الذنب, ''Forgiver of sin''. One scholar says it means God forgives a sin only when forgiveness is deserved: by repentance (توبة), or by an act of obedience bigger than the sin. Next the commentator explains what this view means for the sinner.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:46-49', 'QRTA:razi:40-01', 'razi', 46, 49, 40, 1, 3, 'If past good outweighs the sin, it is minor and cancelled; else major, removed only by repentance.', '["If past good outweighs the sin, it is major and needs repentance; else it is minor.", "If past good outweighs the sin, even a major sin is cancelled without repentance."]', 'Minor and major sins', NULL, '[]', 'This explains that view. Either the sinner did good before whose reward is bigger than this sin''s punishment, or not. If so, the sin is minor (صغيرة) and its punishment is cancelled (يحبط). If not, the sin is major (كبيرة), and its punishment goes only through repentance.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:50-50', 'QRTA:razi:40-01', 'razi', 50, 50, 40, 1, 3, 'His school holds that God may pardon a major sin, and this verse shows it.', '["His school holds that God never pardons a major sin, and this verse shows it.", "His school holds that God may pardon only minor sins, and this verse shows it."]', 'Pardon of major sins', NULL, '[]', 'Now he gives his own school''s view: God may pardon a major sin (الكبيرة). The printed text says ''after repentance'', but the proofs that follow argue for pardon before repentance. He says this verse shows it, and he will explain it from several angles.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:51-54', 'QRTA:razi:40-01', 'razi', 51, 54, 40, 1, 3, 'If forgiving only meant what is owed, God would earn no more praise than any good person.', '["If forgiving only meant what is owed, good people could never forgive at all.", "Since good people also forgive, God''s forgiveness must be just like theirs."]', 'Praise needs more than duty', NULL, '[]', 'First proof. Forgiving a major sin after repentance, and forgiving a minor sin, are things that are owed (واجب). All prophets and good people do what is owed. If ''Forgiver of sin'' meant only this, God would have no special praise above the least obedient person. That is false, so it must mean He forgives major sins before repentance.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:55-56', 'QRTA:razi:40-01', 'razi', 55, 56, 40, 1, 3, 'Forgiving means covering, and a cancelled minor sin no longer exists to be covered.', '["Forgiving means wiping out, and a minor sin is wiped out only by forgiveness.", "Forgiving means covering, and a minor sin stays in place so it can be covered."]', 'Forgiveness as covering', NULL, '[]', 'Second proof. The word الغفران means covering (الستر). You can only cover something that still exists. But in that view a minor sin is already cancelled by the sinner''s many rewards, so it is gone. So ''forgiving'' makes no sense for it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:57-59', 'QRTA:razi:40-01', 'razi', 57, 59, 40, 1, 3, '''Forgiver of sin'' cannot mean major sins after repentance, or it would repeat ''Accepter of repentance''.', '["''Forgiver of sin'' means major sins after repentance, repeating ''Accepter of repentance'' for stress.", "''Accepter of repentance'' cannot mean accepting repentance, or it would repeat ''Forgiver of sin''."]', 'Two names cannot mean the same', NULL, '[]', 'Nor can ''Forgiver of sin'' mean forgiving a major sin after repentance. That is exactly what ''Accepter of repentance'' (قابل التوب) means. If both meant the same, it would be needless repetition (التكرار), which is wrong. So ''Forgiver of sin'' must mean forgiving major sins before repentance.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:60-62', 'QRTA:razi:40-01', 'razi', 60, 62, 40, 1, 3, 'Said as high praise, ''Forgiver of sin'' must carry its greatest sense: forgiving major sins before repentance.', '["Said as a warning, ''Forgiver of sin'' must carry its narrowest sense: forgiving small sins.", "Said as high praise, ''Forgiver of sin'' means forgiving major sins only after repentance."]', 'Praise calls for the fullest sense', NULL, '[]', 'Third proof. ''Forgiver of sin'' comes in a setting of great praise (معرض المدح). So it should be read in the way that gives the greatest praise. That way is forgiving major sins before repentance.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:63-65', 'QRTA:razi:40-01', 'razi', 63, 65, 40, 1, 3, 'Second attribute, ''Accepter of repentance'', has two discussions; the first is on the word التوب.', '["Second attribute, ''Accepter of repentance'', has two discussions, both on the word قابل.", "Second attribute, ''Accepter of repentance'', has one discussion, on who may repent."]', 'Outline of a discussion', NULL, '[]', 'He moves to the second attribute, قابل التوب, ''Accepter of repentance''. He says it has two discussions (بحثان). The first is about the word التوب itself, and there are two views on it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:66-67', 'QRTA:razi:40-01', 'razi', 66, 67, 40, 1, 3, 'التوب is either a verbal noun, or the plural of توبة.', '["التوب is either a verb, or the singular of توبة.", "التوب is a verbal noun that is also the feminine of توبة."]', 'Verbal noun or plural', 'مَصْدَر', '["GT:derivation_type:masdar"]', 'There are two views on التوب. First, it is a verbal noun (مصدر), naming the act of repenting. Second, it is the plural of توبة, meaning many acts of repentance.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:68-70', 'QRTA:razi:40-01', 'razi', 68, 70, 40, 1, 3, 'التوب: a verbal noun like قول, or a plural like تمر; the verbal noun is likelier.', '["التوب may be a verbal noun like قول, or a plural like تمر; the plural is likelier.", "التوب is only a plural like تمر, and never a verbal noun like قول."]', 'Verbal noun is more likely', 'مَصْدَر', '["GT:derivation_type:masdar", "GT:number:plural"]', 'Both are possible. As a verbal noun: تاب يتوب توبا وتوبة, just like قال يقول قولا وقولة. As a plural: توبة and توب, like تمرة ''a date'' and تمر ''dates''. But the verbal noun (المصدر) is likelier, because then the verse means God accepts this act of repenting.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:71-74', 'QRTA:razi:40-01', 'razi', 71, 74, 40, 1, 3, 'His school says accepting repentance is God''s grace, not a duty, or it would bring little praise.', '["His school says accepting repentance is God''s duty, so it brings Him great praise.", "His school says accepting repentance is grace, yet earns the same praise as any good deed."]', 'Accepting repentance as grace', NULL, '[]', 'Second discussion. His school holds that God accepts a sinner''s repentance as a favour (تفضل), not because He must. المعتزلة said it is a duty on God. His school replies that God mentions it as praise, and a mere duty would earn little praise: only what any good person earns by doing duties and avoiding wrong.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:75-77', 'QRTA:razi:40-01', 'razi', 75, 77, 40, 1, 3, 'Problem: ''Severe in punishment'' can describe an indefinite noun, but not a definite one.', '["Problem: ''Severe in punishment'' can describe a definite noun, but not an indefinite one.", "Problem: ''Severe in punishment'' is a verb, so it cannot describe a noun at all."]', 'Adjective and definiteness', 'نعت', '["GT:irab_role:naat", "GT:definiteness:indefinite", "GT:definiteness:definite"]', 'Third attribute: شديد العقاب. A question is raised. This phrase fits as an adjective (نعت) for an indefinite noun (النكرة), but not for a definite one (المعرفة). The examples come next.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:78-80', 'QRTA:razi:40-01', 'razi', 78, 80, 40, 1, 3, 'You say ''a man severe in assault'', not ''عبد الله severe in assault''; and الله is definite.', '["You say ''عبد الله severe in assault'', not ''a man severe in assault''; and الله is indefinite.", "You may say both, since a proper name like الله takes any adjective."]', 'A proper name is definite', 'اسم عَلَم', '["GT:pos:alam", "GT:definiteness:definite", "GT:irab_role:naat", "GT:definiteness:indefinite"]', 'You say مررت برجل شديد البطش, ''I passed a man severe in assault'', with an indefinite man. You do not say it after عبد الله, a known name. الله is a proper name (اسم علم), so it is definite (معرفة). So how can it take a description that only fits indefinite nouns?', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:81-84', 'QRTA:razi:40-01', 'razi', 81, 84, 40, 1, 3, '''Forgiver'' and ''Accepter'' mean a lasting trait, so they fit; ''Severe in punishment'' is still a problem.', '["''Forgiver'' and ''Accepter'' mean acts done now or tomorrow, and that is why they fit.", "''Forgiver'', ''Accepter'' and ''Severe in punishment'' all mean lasting traits, so none is a problem."]', 'Lasting trait versus passing act', NULL, '[]', '''Forgiver of sin'' and ''Accepter of repentance'' are different. They do not mean an act that happens now or tomorrow; they mean a fixed, lasting trait. So they work like ''God of creation'' and ''Lord of the Throne'', which can describe الله. But ''Severe in punishment'' is still a problem.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:85-86', 'QRTA:razi:40-01', 'razi', 85, 86, 40, 1, 3, 'Its underlying form is ''whose punishment is severe'', which is indefinite, so the question stands.', '["Its underlying form is ''the severe one in punishment'', which is definite, so no question arises.", "Its underlying form is ''His punishment is severe'', a full sentence needing no noun."]', 'Underlying form of a phrase', 'التَّقْدِيرُ', '["GT:irab_role:taqdir", "GT:definiteness:indefinite", "GT:pos:sifa", "GT:definiteness:definite"]', 'The reason: شديد العقاب stands for شديدٌ عقابُه, ''whose punishment is severe''. This is its underlying form (التقدير). In that form it is indefinite (نكرة), so it cannot be an attribute (صفة) of a definite noun. That is the question, and several answers follow.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:87-90', 'QRTA:razi:40-01', 'razi', 87, 90, 40, 1, 3, 'First answer: though indefinite, it sits well among definite attributes, as in a verse of سورة البروج.', '["First answer: since it is indefinite, it must be taken out of the list of attributes.", "First answer: it becomes definite by itself, as in a verse of سورة البروج."]', 'Indefinite among definite attributes', 'نَكِرَة', '["GT:pos:sifa", "GT:definiteness:indefinite", "GT:definiteness:definite"]', 'The first answer: yes, this attribute is indefinite (نكرة). But since it comes among other attributes that are definite (معارف), it sits well. A similar mix is in the verse ''And He is the Forgiving, the Loving, Owner of the Throne, the Glorious, Doer of whatever He wills''. Then the second answer begins.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:91-93', 'QRTA:razi:40-01', 'razi', 91, 93, 40, 1, 3, 'Second answer: it is a substitute, since an indefinite may replace a definite; critics found this odd.', '["Second answer: it is an adjective, since an indefinite may describe a definite; critics agreed.", "Second answer: it is a substitute, though a definite may never replace an indefinite."]', 'Reading it as a substitute', 'بدل', '["GT:case:genitive", "GT:irab_role:badal", "GT:definiteness:indefinite", "GT:definiteness:definite", "GT:pos:sifa"]', 'Second answer: شديد is in the genitive (خفض) because it is a substitute (البدل), not an adjective. A substitute may be indefinite for a definite noun, or the reverse. Critics replied that making this one word alone a substitute, in a row of attributes, is clearly out of place (نبوة ظاهرة).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:94-96', 'QRTA:razi:40-01', 'razi', 94, 96, 40, 1, 3, 'Third answer: like ''Forgiver'' and ''Accepter'', ''Severe in punishment'' also means a lasting trait.', '["Third answer: unlike ''Forgiver'' and ''Accepter'', ''Severe in punishment'' means a passing act.", "Third answer: ''Forgiver'' and ''Accepter'' cannot be attributes, so neither can ''Severe in punishment''."]', 'Lasting meaning lets it describe', 'صِفَة', '["GT:pos:sifa"]', 'Third answer. All agree that ''Forgiver of sin and Accepter of repentance'' work as attributes (صفة). They work because they mean something lasting and constant (الدوام والاستمرار). In the same way, ''Severe in punishment'' means something lasting, so it too can describe الله.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:97-98', 'QRTA:razi:40-01', 'razi', 97, 98, 40, 1, 3, 'God''s attributes never come to be; His punishment being severe is always true.', '["God''s attributes come to be over time; His punishment becomes severe when people sin.", "God''s attributes never change, so His punishment is never actually carried out."]', 'God''s attributes do not begin', NULL, '[]', 'Why is it lasting? God''s attributes are free of coming into being or renewing (الحدوث والتجدد). So ''Severe in punishment'' means He is such that His punishment is severe. This is always true; it did not start after a time when it was not. He closes: this is what has been said on the matter.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:99-101', 'QRTA:razi:40-01', 'razi', 99, 101, 40, 1, 3, 'Mercy weighs more: before ''Severe in punishment'' come two names that remove punishment.', '["Punishment weighs more: before ''Severe in punishment'' come two names that confirm it.", "Mercy and punishment weigh the same: one name of each comes before it."]', 'Mercy outweighs punishment', NULL, '[]', 'Second discussion: this verse hints that mercy and grace win out. When God called Himself severe in punishment, He first named two traits that each remove punishment: Forgiver of sin and Accepter of repentance. After it He named a trait showing great mercy, which comes next.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:102-103', 'QRTA:razi:40-01', 'razi', 102, 103, 40, 1, 3, 'With mercy names before it and ''Possessor of bounty'' after it, mercy is the weightier side.', '["Since severity comes last, after all the mercy names, punishment is the weightier side.", "Since ''Possessor of bounty'' comes before severity, both sides weigh the same."]', 'Order of names shows weight', NULL, '[]', 'The name after it is ذي الطول, ''Possessor of bounty''. So ''Severe in punishment'' has two mercy names before it and one after it. This placement shows that the side of mercy and generosity is weightier (أرجح).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:104-107', 'QRTA:razi:40-01', 'razi', 104, 107, 40, 1, 3, 'Question: why is و used between ''Forgiver'' and ''Accepter'', but not before ''Severe in punishment''?', '["Question: why is و used before ''Severe in punishment'', but not between ''Forgiver'' and ''Accepter''?", "Question: why is و used between all the names except the very last one?"]', 'Why و appears in one place', 'وَاو العَطْف', '["GT:harf_maani:atf"]', 'Third discussion. Someone may ask: the verse says ''Forgiver of sin AND Accepter of repentance'', with the joining letter و. But there is no و before ''Severe in punishment''. What is the reason for the difference?', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:108-110', 'QRTA:razi:40-01', 'razi', 108, 110, 40, 1, 3, 'Without و, one might think forgiving sin and accepting repentance were the same; و rules that out.', '["Without و, one might think they were different; و shows they mean the same.", "With و, one might think forgiving sin and accepting repentance were the same."]', 'و marks two different things', 'وَاو العَطْف', '["GT:harf_maani:atf"]', 'Answer: without the و, someone might think ''Forgiver of sin'' means nothing more than ''Accepter of repentance''. Adding و removes that idea. The و tells us these are two separate traits.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:111-112', 'QRTA:razi:40-01', 'razi', 111, 112, 40, 1, 3, 'A thing cannot be joined to itself; severity is clearly different, so no و is needed.', '["A thing can be joined to itself; severity equals forgiving, so و is dropped.", "A thing cannot be joined to itself; severity is like forgiving, so و is dropped."]', 'Nothing is joined to itself', 'عطف', '["GT:irab_role:atf", "GT:harf_maani:atf"]', 'The reason: you cannot join (عطف) a thing to itself, so و always marks two different things. ''Severe in punishment'' is plainly different from forgiving and accepting repentance. Since anyone can see the difference, there was no need for و.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:113-116', 'QRTA:razi:40-01', 'razi', 113, 116, 40, 1, 3, 'ذي الطول means ''Possessor of favour''; Arabs say طال علينا for ''he did us a favour''.', '["ذي الطول means ''Possessor of length'', from طال ''to last long'' in time.", "ذي الطول means ''Possessor of power''; Arabs say طال علينا for ''he ruled over us''."]', 'Meaning of الطول', NULL, '[]', 'Fourth attribute: ذي الطول, which means ''Possessor of favour'' (التفضل). The Arabs say طال علينا طولا, meaning he did us a favour. They also say طل علي بفضلك, ''grant me your favour''. So here الطول means generous giving, not length.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:117-119', 'QRTA:razi:40-01', 'razi', 117, 119, 40, 1, 3, 'The same word appears in ''those of means among them'' and ''whoever cannot afford the means''.', '["The same word appears in ''those of length among them'', meaning those who live long.", "The same word appears in ''whoever cannot afford the means'', meaning those short of time."]', 'Same word in other verses', NULL, '[]', 'He shows the word in other verses. أولو الطول منهم in سورة التوبة means ''those of means among them''. In سورة النساء, ومن لم يستطع منكم طولا means ''whoever among you cannot afford the means''. He says this was already explained there.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:120-121', 'QRTA:razi:40-01', 'razi', 120, 121, 40, 1, 3, '''Severe in punishment'' means He brings severe punishment that is never wrong of Him.', '["''Severe in punishment'' means He brings severe punishment, even when it is wrong.", "''Severe in punishment'' means He never brings punishment, since that would be ugly."]', 'Punishment that is not wrong', NULL, '[]', 'He now links ''Severe in punishment'' with the next name. Calling Himself severe in punishment means He brings severe punishment that is not ugly (قبيح) for Him to bring. In fact, God can never be described as doing anything ugly.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:122-123', 'QRTA:razi:40-01', 'razi', 122, 123, 40, 1, 3, 'So ''Possessor of bounty'' means His favour in leaving a punishment He has the right to give.', '["So ''Possessor of bounty'' means His favour in giving the punishment He has the right to give.", "So ''Possessor of bounty'' means His wealth, which He gives only after punishing."]', 'Bounty as holding back punishment', NULL, '[]', 'Then comes ''Possessor of bounty'', meaning ''Possessor of favour''. Coming right after severe punishment, it must mean this: His favour is that He leaves (يترك) a punishment He is entitled to give.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:124-126', 'QRTA:razi:40-01', 'razi', 124, 126, 40, 1, 3, 'Bounty here points to the punishment just named, so pardoning major sins is possible.', '["Bounty here means wealth in general, so pardoning major sins is impossible.", "Bounty here is named as wealth, with no link to the punishment before it."]', 'Context explains a vague word', NULL, '[]', 'Why this reading? The verse says He has bounty but not in what. To remove the vagueness (الإجمال), it must point to what was just named: punishment He could rightly give. So He may leave a punishment that would be right to give, which shows that pardon for people of major sins is possible.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:127-130', 'QRTA:razi:40-01', 'razi', 127, 130, 40, 1, 3, '''No god but He'': a sharer in His mercy would weaken the need to serve Him.', '["''No god but He'': a sharer in His mercy would strengthen the need to serve Him.", "''No god but He'': other gods share His mercy, so all of them are served."]', 'Oneness completes hope and fear', NULL, '[]', 'Fifth attribute: pure oneness, ''There is no god but He''. God has described Himself with mercy and favour. If another god shared these equally, people would not need to serve Him so much. But since He is one, with no partner and no likeness, that need is strong, so oneness makes hope (الترغيب) and warning (الترهيب) complete.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:131-132', 'QRTA:razi:40-01', 'razi', 131, 132, 40, 1, 3, '''To Him is the final return'' also makes one more eager to serve Him.', '["''To Him is the final return'' weakens the fear of disobeying Him.", "''To Him is the final return'' means people return to Him only in this life."]', 'The return to God', NULL, '[]', 'Sixth attribute: إليه المصير, ''to Him is the final return''. This trait too makes a person more eager to accept being His servant (عبودية).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:133-135', 'QRTA:razi:40-01', 'razi', 133, 135, 40, 1, 3, 'Without resurrection, fear of disobeying Him would be weak; with it, fear and care are complete.', '["Even without resurrection, fear of disobeying Him would be strong because He is one.", "With resurrection, fear is less needed, because His mercy is already certain."]', 'Resurrection gives fear its weight', NULL, '[]', 'Suppose God had favour and generosity and no partner. If there were no gathering and raising of the dead (الحشر والنشر), people would not strongly fear disobeying Him. But since the Resurrection is real, fear is greater and caution more complete. That is why God named these attributes; the line then starts a new point about the word إلى.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:razi:40-01:136-136', 'QRTA:razi:40-01', 'razi', 136, 136, 40, 1, 3, 'Some take إلى here as marking an end-point; he says the answer is in many places.', '["Some take إلى here as marking a starting point; he answers it fully right here.", "Some take إلى here as meaning ''with''; he says the answer is in many places."]', 'إلى marking an end-point', 'إِلَى لانْتِهَاء الغَايَة', '["GT:harf_maani:ila_intiha_ghaya"]', 'Some who liken God to created things (أهل التشبيه) used the word إلى in ''to Him is the return'' as a proof. They said إلى marks the end-point of a limit (انتهاء الغاية). He does not answer here; he says the answer is given in many places in his book.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:1-4', 'QRTA:alusi:40-01', 'alusi', 1, 4, 40, 1, 3, 'The surah has three names and is Meccan, though one view excepts verse 55.', '["The surah has three names and is Medinan, except verse 55 which is Meccan.", "Verse 55 is excepted because prayer in Medina was only two units with no set times."]', 'Names and place of revelation', NULL, '[]', 'The surah is called المؤمن, غافر and الطول. Reports say it came down in Mecca (مكية), and a consensus is even claimed. One view makes an exception for verse 55, ''glorify with the praise of your Lord'', taking it to mean the set prayers. Those prayers came in Medina; in Mecca prayer was just two units (ركعتين) with no fixed times.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:5-6', 'QRTA:alusi:40-01', 'alusi', 5, 6, 40, 1, 3, 'Most say the five prayers came in Mecca, and ''glorify'' need not mean prayer anyway.', '["Most say the five prayers were first ordered in Medina, not in Mecca.", "The verse must mean prayer, so the exception for verse 55 stands."]', 'Answering a claimed exception', NULL, '[]', 'The commentator rejects that exception. The view of most scholars is that the five daily prayers were made due in Mecca. Also, التسبيح (''glorify'') in verse 55 does not have to mean prayer at all. So there is no reason to call that verse Medinan.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:7-10', 'QRTA:alusi:40-01', 'alusi', 7, 10, 40, 1, 3, 'Another view excepts verse 35 as Medinan, but its report does not prove a Medinan setting.', '["Verse 35 is clearly Medinan, since a report says it came down about the Jews.", "Another view excepts verse 35, and the commentator accepts it because of that report."]', 'Is this verse Medinan?', NULL, '[]', 'Some said the surah is Meccan except verse 35, ''those who dispute'', which they called Medinan. Their proof is a report that it came down about the Jews when they spoke of the Antichrist (الدجال). The commentator says this report does not plainly state that it came down in Medina.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:11-13', 'QRTA:alusi:40-01', 'alusi', 11, 13, 40, 1, 3, '''The verse came down about X'' can mean its cause, or just that X falls under it.', '["''The verse came down about X'' always names the event that caused the verse.", "''The verse came down about X'' means X is the only thing the verse is about."]', 'What ''it came down about'' means', NULL, '[]', 'The phrase نزلت الآية في كذا has two uses. Sometimes it names the cause of revelation (سبب النزول). Other times it only means the case is included in the verse, even if it was not the cause, like saying ''this verse means such-and-such''. So the report about verse 35 may not be a cause at all.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:14-16', 'QRTA:alusi:40-01', 'alusi', 14, 16, 40, 1, 3, 'When early Muslims said ''it came down about X'', they often meant the verse covers that ruling.', '["When early Muslims said ''it came down about X'', they were reporting the event behind it.", "Early Muslims used the phrase to show that a ruling had been cancelled by the verse."]', 'Proving a ruling, not telling events', NULL, '[]', 'This was a known habit of the Companions and their students. When one of them said a verse came down about something, he usually meant the verse contains that ruling (الحكم). That is using the verse as proof for a ruling, not reporting what happened. So such reports do not settle when or where a verse came down.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:17-17', 'QRTA:alusi:40-01', 'alusi', 17, 17, 40, 1, 3, 'Still, a report given later is almost a clear statement that verse 35 came down in Medina.', '["So no report anywhere supports a Medinan setting for verse 35.", "A report given later clearly proves that verse 35 came down in Mecca."]', 'Weighing the evidence', NULL, '[]', 'The commentator softens his point. He has said the first report is not a clear proof (نص). But another report, which he will give later, comes close to being one. So the question about verse 35 stays partly open.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:18-19', 'QRTA:alusi:40-01', 'alusi', 18, 19, 40, 1, 3, 'Different counts give the surah 85, 84 or 82 verses, and 86 has also been said.', '["Every count agrees that the surah has exactly 85 verses.", "The largest count gives the surah 82 verses, and the smallest gives 86."]', 'Counting the verses', NULL, '[]', 'The number of verses differs between the counting traditions. Kufa and Syria count 85, the Hijaz 84, and Basra 82. Others said 86, and one more figure follows in the next line.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:20-21', 'QRTA:alusi:40-01', 'alusi', 20, 21, 40, 1, 3, 'After الزمر ends with both fates, this surah opens with forgiveness to invite unbelievers to faith.', '["After الزمر ends with both fates, this surah opens with punishment to warn the believers.", "This surah opens with forgiveness because الزمر had already called the unbeliever to faith."]', 'Link between neighbouring surahs', 'المناسبة', '["GT:balagha_maani:munasaba"]', 'Here المناسبة means the link between the end of one surah and the start of the next. الزمر ends by showing where the unbeliever and the believer end up. This surah then begins by calling God ''Forgiver of sin, Accepter of repentance''. That is an open call to the unbeliever to believe and give up what he is doing.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:22-24', 'QRTA:alusi:40-01', 'alusi', 22, 24, 40, 1, 3, 'Both surahs describe the Resurrection and the unbelievers'' state; this one gives more detail.', '["Both surahs describe the Resurrection, but الزمر gives more detail than this one.", "The two surahs are linked only by their openings, not by their content."]', 'Link between neighbouring surahs', 'المناسبة', '["GT:balagha_maani:munasaba"]', 'Beyond the openings, the two surahs as wholes share several links (المناسبة). It is enough to note that both describe the Day of Resurrection and the state of the unbelievers there, at the gathering and in the Fire. This surah spells out details that الزمر left brief.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:25-25', 'QRTA:alusi:40-01', 'alusi', 25, 25, 40, 1, 3, 'The seven حم surahs follow الزمر because their openings match: the Book sent down.', '["The seven حم surahs follow الزمر because they all came down in the same year.", "The seven حم surahs come before الزمر because they open with the letters حم."]', 'Why the surahs are ordered so', NULL, '[]', 'The seven surahs that begin with حم (الحواميم) are placed right after الزمر. The reason given is that their openings are alike. They begin, like الزمر, with the sending down of the Book (تنزيل الكتاب).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:26-27', 'QRTA:alusi:40-01', 'alusi', 26, 27, 40, 1, 3, 'The حم surahs stand together because they share حم, mention of the Book, and a Meccan origin.', '["The حم surahs stand together because they share the same length and number of verses.", "The حم surahs were put together later, not in the order in which they came down."]', 'Link that groups the حم surahs', 'المناسبة', '["GT:balagha_maani:munasaba"]', 'In one early copy (مصحف) of the Quran, الزمر itself begins with حم, which makes the link very strong (مناسبة جليلة). The حم surahs sit in a row because they all open with حم, all mention the Book, and are all Meccan. A report even says they came down one after another right after الزمر, in the same order as in the Quran.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:28-29', 'QRTA:alusi:40-01', 'alusi', 28, 29, 40, 1, 3, 'Many reports praise the حم surahs; one calls them the kernel (لباب) of the Quran.', '["One report calls the حم surahs the outer shell that guards the Quran.", "One report says everything has a kernel, and the kernel of the حم surahs is the Quran."]', 'Merit of the حم surahs', NULL, '[]', 'Many reports speak of the merit (فضل) of these surahs. The first says everything has a لباب, its inner core or best part. The core of the Quran is the حم surahs.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:30-31', 'QRTA:alusi:40-01', 'alusi', 30, 31, 40, 1, 3, 'Another report calls the حم surahs the brocade (ديباج) of the Quran.', '["Another report calls the حم surahs the plain cover that wraps the whole Quran.", "Another report says the brocade of the حم surahs is the rest of the Quran."]', 'Merit of the حم surahs', NULL, '[]', 'Another report calls the حم surahs ديباج القرآن. ديباج is fine silk brocade, the richest kind of cloth. The picture is of beauty and high value.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:32-33', 'QRTA:alusi:40-01', 'alusi', 32, 33, 40, 1, 3, 'That saying is also traced to the Prophet, and another calls them a meadow of Paradise.', '["That saying is denied as the Prophet''s, and another calls them a gate of Paradise.", "Another report says the meadows of Paradise are described inside the حم surahs."]', 'Report traced to the Prophet', NULL, '[]', 'The ''brocade'' saying is also reported مرفوعا, that is, traced back to the Prophet himself. Another report traced to the Prophet says the حم surahs are a روضة, a garden or meadow, among the meadows of Paradise. Both stress how blessed these surahs are.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:34-35', 'QRTA:alusi:40-01', 'alusi', 34, 35, 40, 1, 3, 'The حم surahs used to be called ''the brides'' (العرائس).', '["The brides (العرائس) was a name once given to the long surahs, not the حم ones.", "The حم surahs used to be called ''the brides'' because they were read at weddings."]', 'Another name for the حم surahs', NULL, '[]', 'An early report says people used to call the حم surahs العرائس, ''the brides''. The name points again to their beauty and honour.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:36-39', 'QRTA:alusi:40-01', 'alusi', 36, 39, 40, 1, 3, 'Groups of surahs replace earlier books; حم and المفصل are the Prophet''s special gift.', '["The حم surahs replace the Torah, and the long surahs replace the Psalms.", "حم and المفصل were also recited by the prophets before him."]', 'Groups of surahs and earlier books', NULL, '[]', 'In this report the Prophet lists groups of surahs. The seven long ones (السبع الطوال) stand in place of the Torah. The surahs from those opening with الر up to those opening with طس stand in place of the Gospel, and those from طس up to حم in place of the Psalms. The حم surahs and the short surahs (المفصل) are a gift no prophet before him recited.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:40-42', 'QRTA:alusi:40-01', 'alusi', 40, 42, 40, 1, 3, 'The seven حم surahs will each stand at one of Hell''s seven gates to shield their readers.', '["The seven حم surahs will each open one of Hell''s seven gates for those who ignored them.", "Each حم surah will ask God to let its reciter enter Paradise through its own gate."]', 'Merit of the حم surahs', NULL, '[]', 'This report pairs the seven حم surahs with the seven gates of Hell. Each surah will stand at one gate and ask God not to let in anyone who believed in it and recited it. So these surahs act as a shield for their faithful readers.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:43-46', 'QRTA:alusi:40-01', 'alusi', 43, 46, 40, 1, 3, 'Reciting حم to ''to Him is the return'' plus the Throne Verse at dawn protects until evening.', '["Reciting the whole surah plus the Throne Verse at dawn protects for a full week.", "Reciting حم to ''to Him is the return'' protects at dawn, but the Throne Verse only at night."]', 'Merit of particular verses', NULL, '[]', 'Some reports praise particular verses of this surah. One says that whoever recites from حم up to ''to Him is the final return'' (verse 3) with the Throne Verse in the morning is protected until evening. Reciting them in the evening protects until morning. These are the very verses studied here.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:47-49', 'QRTA:alusi:40-01', 'alusi', 47, 49, 40, 1, 3, 'حم is read with a full ا and silent م, a tilted ا, or a vowelled م.', '["All readers agree that حم is read with a tilted ا and a vowelled م.", "Some readers give the م an ''a'' vowel to make it sound heavier and fuller."]', 'Tilting a vowel toward ''i''', 'الإمالة', '["GT:irab_sign:sukun", "GT:phonotactic:imala", "GT:irab_sign:fatha", "GT:phonotactic:iltiqa_sakinayn"]', 'The main reading says حم with a full, open ا (تفخيم) and a silent م (السكون). Several readers use الإمالة: they tilt the ا toward an ''i'' sound, some fully and some halfway (بين بين). Two readers give the م a فتحة, because two silent letters meet (التقاء الساكنين) and the فتحة is the lightest vowel to break them.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:50-52', 'QRTA:alusi:40-01', 'alusi', 50, 52, 40, 1, 3, 'The ''a'' on م may be accusative under an unsaid ''recite!''; حم is then not fully declined.', '["The ''a'' on م marks the accusative because حم is the object of ''sent down'' in verse 2.", "حم is not fully declined because it is masculine and a common noun."]', 'Nouns not fully declined', 'مَنْعُ الصَّرْفِ', '["GT:case:accusative", "GT:irab_role:idmar_al_amil", "GT:noun_process:man_al_sarf", "GT:gender:feminine"]', 'Another way to explain the ''a'' on the م: it is accusative (نصب) because the verb اقرأ (''recite'') is understood but not said (إضمار). Then حم is a name that is not fully declined (منع من الصرف). Either it is a proper name and feminine, since it means ''the surah'', or a proper name that looks foreign, because the pattern فاعيل is not an Arab pattern, as in قابيل and هابيل.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:53-53', 'QRTA:alusi:40-01', 'alusi', 53, 53, 40, 1, 3, 'A better reason for non-declension is that حم is definite and compound.', '["A better reason for full declension is that حم is definite and compound.", "A better reason for non-declension is that حم is indefinite and a single word."]', 'Definiteness and compounding', NULL, '["GT:definiteness:definite"]', 'Another commentary says there is a better way to explain why حم is not fully declined. It is definite (التعريف) as a name, and it is compound (التركيب), built from more than one part.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:54-55', 'QRTA:alusi:40-01', 'alusi', 54, 55, 40, 1, 3, 'Other readings: ''i'' on م for two silent letters, or ''u'' as a subject or predicate.', '["Other readings: ''i'' on م as a genitive case, or ''u'' only to ease pronunciation.", "Other readings: ''u'' on م for two silent letters, or ''i'' as a subject or predicate."]', 'Meeting of two silent letters', 'التقاء الساكنين', '["GT:irab_sign:kasra", "GT:phonotactic:iltiqa_sakinayn", "GT:case:nominative", "GT:irab_role:mubtada", "GT:irab_role:khabar"]', 'One reader gives the م a كسرة. This is the basic rule when two silent letters meet (التقاء الساكنين), as in the word جير. Another reads it with a ضمة (رفع), which looks like a real case ending (إعراب). Then حم is either the subject (مبتدأ) or the predicate (خبر) of a subject left out (محذوف).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:56-58', 'QRTA:alusi:40-01', 'alusi', 56, 58, 40, 1, 3, 'حم has two plurals, حواميم and حاميمات, and both are backed by poetry or reports.', '["حم has two plurals, but only حاميمات is found in real reports.", "The plural حواميم came only from mistakes made by non-Arab narrators."]', 'The plural of حم', NULL, '[]', 'حم is made plural in two ways: حواميم and حاميمات. A line of poetry uses حاميمات. Several reports given earlier use حواميم. The commentator does not think anyone would reject all those reports or claim the word was changed by non-Arab narrators.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:59-60', 'QRTA:alusi:40-01', 'alusi', 59, 60, 40, 1, 3, 'A poem also uses الحواميم, yet some scholars held that one must not say حواميم.', '["A poem uses الحواميم, so all scholars agreed that this plural is correct.", "A poem rejects the word حواميم and uses المفصل in its place."]', 'The plural of حم', NULL, '[]', 'Another poem swears by groups of surahs: the seven long ones, the hundreds, the doubled ones, the طس surahs, the حم surahs and المفصل. It uses الحواميم as a normal plural. Even so, some language scholars held that one does not say حواميم.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:61-63', 'QRTA:alusi:40-01', 'alusi', 61, 63, 40, 1, 3, 'Some held الحواميم is not real Arabic; the correct form is آل حم.', '["Some held آل حم is not real Arabic; the correct form is الحواميم.", "Some held الحواميم is correct Arabic, but آل حم is the finer style."]', 'آل حم instead of الحواميم', NULL, '[]', 'One grammarian said that الحواميم, as common people say it, is not the speech of the Arabs. A language scholar said it is a mistake to say ''I read الحواميم''. The right way, he said, is ''I read آل حم''.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:64-65', 'QRTA:alusi:40-01', 'alusi', 64, 65, 40, 1, 3, 'A report and a poem both say آل حم; the same objection is made to الطواسين.', '["A report and a poem both say آل حم, so الطواسين is the accepted plural.", "A report says آل حم are hard, rocky places that tire the reader."]', 'آل حم in reports and poetry', NULL, '[]', 'These scholars support آل حم with a report: ''When I reach آل حم, I reach soft, level meadows that I enjoy.'' A line of poetry also says ''in آل حم''. In their view الطواسين and الطواسيم (with م instead of ن) are wrong in the same way.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:66-66', 'QRTA:alusi:40-01', 'alusi', 66, 66, 40, 1, 3, 'The reports and poems already given are enough to refute those who reject حواميم.', '["The reports already given are enough to refute those who accept حواميم.", "More proof is needed before the view of those scholars can be rejected."]', 'Answering an objection', NULL, '[]', 'The commentator answers them briefly. The reports and poems he has already given use حواميم. That is enough to show their rejection is wrong.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:67-69', 'QRTA:alusi:40-01', 'alusi', 67, 69, 40, 1, 3, 'آل حم is correct too, but آل there is not ''family''; it comes before compound names.', '["آل حم is correct, and آل there means ''family'', like the family of a man.", "آل is put before compound names so that they can be made definite."]', 'آل before compound names', NULL, '["GT:number:dual", "GT:number:plural", "GT:sentence_class:jumla"]', 'The commentator grants that آل حم is also heard and accepted. But آل here is not the well-known آل meaning ''family'' (الأهل). It is a word put before names that cannot be made dual (تثنية) or plural (جمع), such as the compound name تأبط شرا. Such a name is a whole sentence (جملة), so it cannot take a dual or plural ending.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:70-72', 'QRTA:alusi:40-01', 'alusi', 70, 72, 40, 1, 3, 'Arabs put آل or ذوا before such names, so آل حم simply means the حم surahs.', '["Arabs put آل or ذوا after such names, so آل حم means the family of حم.", "Arabs put آل before such names, so آل حم means one single surah named حم."]', 'Figurative use of آل', 'المَجَاز', '["GT:balagha_bayan:majaz"]', 'Since a sentence-name cannot be made dual or plural, the Arabs put آل or ذوا before it: ''آل تأبط شرا came to me'' means the two men, or the men, with that name. So آل حم means الحواميم, and آل has the sense of ذو, ''having''. It is a figure of speech (مجاز) for a link in meaning, not a link of family.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:73-74', 'QRTA:alusi:40-01', 'alusi', 73, 74, 40, 1, 3, 'Others only hinted at this; another view prefers the plural ذوات حم, ''surahs carrying حم''.', '["Others stated this fully; another view prefers the plural حاميمات over ذوات حم.", "ذوات حم means ''the owners of حم'', the people who recite these surahs."]', 'The plural of حم', NULL, '[]', 'Earlier grammarians hint at this idea but never spell it out, so the reader should keep it in mind. Another commentary says the best plural is ذوات حم, rather than حواميم or حاميمات. It means ''the surahs that come with this word حم''.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:75-76', 'QRTA:alusi:40-01', 'alusi', 75, 76, 40, 1, 3, 'تنزيل is parsed as in الزمر, but here it may also be the predicate of حم.', '["The grammar of تنزيل differs from الزمر, since here it must be the subject of حم.", "The grammar of تنزيل is as in الزمر, and here حم is the predicate of تنزيل."]', 'تنزيل as a predicate', 'خبر', '["GT:irab_role:khabar"]', 'Verse 2, ''The sending down of the Book is from God, the Almighty, the All-Knowing'', has the same words as the start of الزمر, so its grammar (إعراب) is the same. The one new option here is that تنزيل can be the predicate (خبر) of حم. Then the meaning is ''حم is the sending down of the Book''.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:77-78', 'QRTA:alusi:40-01', 'alusi', 77, 78, 40, 1, 3, 'The two names fit the Quran''s matchless wonder and knowledge; ''All-Knowing'' replaces ''All-Wise'' for variety.', '["The two names fit the Quran''s ease and simplicity; ''All-Knowing'' replaces ''All-Wise'' for rhyme.", "''All-Wise'' is used here instead of ''All-Knowing'' just to vary the wording."]', 'Why these two names of God', NULL, '[]', 'Perhaps ''the Almighty, the All-Knowing'' are chosen because the Quran cannot be matched (إعجاز) and holds more kinds of knowledge than any mind can take in. Or it is like the two names at the start of الزمر: one whose knowledge is vast must also be wise. So ''the All-Knowing'' is used here instead of ''the All-Wise'' just for variety (تفنن).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:79-81', 'QRTA:alusi:40-01', 'alusi', 79, 81, 40, 1, 3, 'The names in verse 3 describe God; three give hope, one gives fear, all urging faith.', '["The names in verse 3 describe the Book; three give fear and one gives hope.", "The hope and fear names only praise God; they do not urge the reader to act."]', 'Stirring hope and fear', NULL, '["GT:irab_role:naat"]', '''Forgiver of sin, Accepter of repentance, severe in punishment, Possessor of bounty'' are adjectives (نعت) of the name الله, like ''the Almighty, the All-Knowing''. Three of them stir hope (الترغيب), and ''severe in punishment'' stirs fear (الترهيب). Together they push the reader toward what the Book is sent for: belief in one God (التوحيد), belief in the rising after death, and turning fully to God.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:82-83', 'QRTA:alusi:40-01', 'alusi', 82, 83, 40, 1, 3, 'غافر and قابل show a lasting quality, so their annexation is pure and makes them definite.', '["غافر and قابل show a passing action, so their annexation stays loose and indefinite.", "غافر and قابل are definite because they carry the article ال."]', 'Pure annexation', 'الإضافة المعنوية', '["GT:derivation_type:active_participle", "GT:definiteness:definite", "GT:idafa_kind:manawiya", "GT:irab_role:naat"]', 'غافر and قابل are active participles (اسم الفاعل), which can show an action at a certain time. Here they do not; they show a lasting, constant quality (الثبوت). So their annexation to the definite word after them is pure (محضة) and makes them definite. That is why they can describe الله, the most definite of all nouns, while ذي الطول raises no problem at all.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:84-86', 'QRTA:alusi:40-01', 'alusi', 84, 86, 40, 1, 3, 'شديد العقاب is a problem: a الصفة المشبهة never becomes definite by annexation.', '["شديد العقاب is no problem, since a الصفة المشبهة becomes definite by annexation.", "شديد العقاب is a problem because شديد is an active participle showing a passing act."]', 'Adjective like a participle', 'الصفة المشبّهة', '["GT:derivation_type:sifa_mushabbaha", "GT:idafa_kind:lafziya", "GT:definiteness:definite", "GT:idafa_kind:manawiya", "GT:irab_role:naat"]', 'شديد is an adjective that resembles the participle (الصفة المشبهة). The rule says a word with loose annexation (غير محضة) can be taken as pure and so become definite, except this kind of adjective, which never does. So it seems an indefinite word is describing الله. Because of this, one view says شديد العقاب is a substitute (بدل), not an adjective.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:87-88', 'QRTA:alusi:40-01', 'alusi', 87, 88, 40, 1, 3, 'Calling it a substitute is objected to: a substitute among adjectives jars the sense.', '["Calling it a substitute is preferred, since a substitute fits smoothly among adjectives.", "The objection is that an adjective shows the described noun is not the main aim."]', 'A substitute among adjectives', 'بدل', '["GT:irab_role:badal", "GT:irab_role:naat"]', 'The objection: putting a substitute (بدل) in the middle of a list of adjectives sounds badly out of place. An adjective shows that the noun it describes is the real aim. A substitute shows the opposite, so it is like making that noun the aim all over again after setting it aside.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:89-90', 'QRTA:alusi:40-01', 'alusi', 89, 90, 40, 1, 3, 'The problem only arises if this adjective can never become definite; another school says it can.', '["The problem only arises if this adjective can become definite; another school says it never can.", "Both schools say this adjective never becomes definite, so the problem has no answer."]', 'Definiteness by annexation', 'التعريف بالإضافة', '["GT:derivation_type:sifa_mushabbaha", "GT:balagha_maani:tarif_bil_idafa", "GT:definiteness:definite", "GT:pos:sifa"]', 'The answer: this is a problem only for the Basra school, which says الصفة المشبهة never becomes definite by annexation (الإضافة). The Kufa school says it can, like other adjectives, so it may describe a definite noun, as in مررت بزيد حسن الوجه. On that view there is no problem.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:91-92', 'QRTA:alusi:40-01', 'alusi', 91, 92, 40, 1, 3, 'Even on the strict view, شديد can be read as مشدد, an active participle.', '["On the strict view, شديد is read as a verbal noun meaning ''severity'' itself.", "On the strict view, شديد is read as a passive participle meaning ''made severe''."]', 'Taking شديد as an active participle', 'اسم الفاعل', '["GT:derivation_type:active_participle"]', 'Even on the strict first view there is a way out. شديد can be taken in the sense of مشدد, ''the one who makes it severe'', the active participle (اسم الفاعل) of أشدّه. Arabic does this elsewhere: أذين is used for مؤذن, ''the one who calls''. Then شديد takes the active participle''s rule.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:93-94', 'QRTA:alusi:40-01', 'alusi', 93, 94, 40, 1, 3, 'Or شديد was first الشديد عقابه; ال was dropped since, among adjectives, no confusion arises.', '["Or شديد was first الشديد عقابه; ال was dropped to make it a substitute.", "Or ال was added to شديد later to match the other adjectives around it."]', 'Dropping the article', 'الحذف', '["GT:balagha_maani:tarif_bil_lam", "GT:balagha_maani:hadhf", "GT:pos:sifa", "GT:irab_role:naat", "GT:irab_role:badal", "GT:balagha_badi:mushakala", "GT:irab_role:taqdir"]', 'Another way out: شديد is really definite with ال. The full form is الشديد عقابه, ''the One whose punishment is severe''. The ال was dropped (الحذف) because, standing among adjectives, it can only be read as an adjective. It was also dropped to match (مشاكلة) the other adjectives, which have no ال, and what is understood counts as if it were there.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:95-96', 'QRTA:alusi:40-01', 'alusi', 95, 96, 40, 1, 3, 'Arabs bend grammar rules for matching words, even making a single word dual.', '["Arabs never bend grammar rules for matching words, so the dual here is a real pair.", "Arabs bend rules for matching words, even making a dual word single."]', 'Matching words', 'المُشَاكَلَة', '["GT:balagha_badi:mushakala"]', 'To support this, the commentator notes that the Arabs changed much of their speech from its normal rules for the sake of matching (المشاكلة). In one saying, a word for something single is put in the dual only to match a nearby word for a pair. So dropping ال to match the nearby adjectives is a known habit.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:97-98', 'QRTA:alusi:40-01', 'alusi', 97, 98, 40, 1, 3, 'Some let all these words be substitutes, with شديد العقاب left indefinite to stress severity.', '["Some let all these words be adjectives, with شديد العقاب made definite to stress mercy.", "شديد العقاب is left vague to soften the warning, since mercy comes first."]', 'Indefiniteness for emphasis', 'التنكير', '["GT:irab_role:badal", "GT:balagha_maani:tankir"]', 'Some allowed every one of these following words (التوابع) to be a substitute (بدل). On this view شديد العقاب is left indefinite (التنكير) and vague on purpose. It shows a severity so great that nothing is worse or more bitter, which makes the warning stronger.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:99-100', 'QRTA:alusi:40-01', 'alusi', 99, 100, 40, 1, 3, 'Making them all substitutes jars badly, especially ''the Almighty'' as a substitute for ''God''.', '["Making them all substitutes fits well, especially ''the Almighty'' as a substitute for ''God''.", "Making them all substitutes jars, especially ''God'' as a substitute for ''the Almighty''."]', 'A fitting opening', 'براعة الاستهلال', '["GT:irab_role:badal", "GT:pos:alam", "GT:balagha_badi:baraat_istihlal"]', 'Another commentary says making them all substitutes is badly out of place. This is worst for العزيز as a substitute for الله. الله is the proper name (العلم) that gathers all the attributes and can mean nothing else. Such a reading spoils the beauty of the opening (براعة الاستهلال).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:101-102', 'QRTA:alusi:40-01', 'alusi', 101, 102, 40, 1, 3, 'Another view lets only ''Forgiver'' and ''Accepter'' be substitutes, as indefinites; this was already answered.', '["Another view lets only ''Almighty'' and ''All-Knowing'' be substitutes, as indefinites.", "Another view makes ''Forgiver'' and ''Accepter'' definite adjectives, and this is accepted."]', 'Substitute', 'بدل', '["GT:irab_role:badal", "GT:definiteness:indefinite"]', 'One view allows غافر الذنب and قابل التوب, but not the words before them, to be two substitutes (بدل). On that view the two words are indefinite (نكرة). The commentator says the reader already knows what is wrong with this from what came before.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:103-105', 'QRTA:alusi:40-01', 'alusi', 103, 105, 40, 1, 3, 'A substitute of changing one''s mind can repeat; for other kinds, no clear ruling is known.', '["Every kind of substitute may repeat freely, as all grammarians clearly state.", "A substitute of a substitute is forbidden, but many substitutes for one word are fine."]', 'Can substitutes repeat?', NULL, '["GT:irab_role:badal"]', 'The question now is whether one word can have several substitutes. For the substitute of changing one''s mind (بدل البداء), repeating is possible. For the whole-for-whole, part-for-whole and inclusion types, no clear ruling is known. Some say a substitute of a substitute is allowed, but not several substitutes for one word (المبدل منه).', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:106-109', 'QRTA:alusi:40-01', 'alusi', 106, 109, 40, 1, 3, 'Others say grammarians clearly allow several substitutes, so that objection fails.', '["Others say grammarians clearly forbid several substitutes, so that objection stands.", "Others say substitutes are common among derived nouns, so rarity is no issue."]', 'Defending the substitute reading', 'بدل', '["GT:irab_role:badal", "GT:form_family:noun_derivatives", "GT:definiteness:indefinite", "GT:definiteness:definite", "GT:irab_role:naat"]', 'Another view holds that the grammarians openly allowed several substitutes. On this view the substitute reading is not hurt by three points: substitutes are rare among derived words (المشتقات); an indefinite word should not replace a definite one unless it is described; and the claim that grammarians never mention several substitutes. The grammarians said the opposite on all of these.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:110-111', 'QRTA:alusi:40-01', 'alusi', 110, 111, 40, 1, 3, 'The commentator rejects every substitute reading; التوب is a verbal noun or a collective noun.', '["The commentator accepts some substitute readings; التوب is a plural of توبة.", "The commentator rejects substitutes; التوب is a verbal noun meaning ''forgiveness''."]', 'Two readings of التوب', NULL, '["GT:irab_role:badal", "GT:derivation_type:masdar"]', 'His own view: reading these words as substitutes (الإبدال) is worth nothing, for all of them or for some. التوب can be a verbal noun (المصدر), like أوب, meaning ''returning''. Or it can be a collective noun (اسم جمع) for توبة, like تمر ''dates'' and تمرة ''one date''.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:112-113', 'QRTA:alusi:40-01', 'alusi', 112, 113, 40, 1, 3, 'الطول covers reward too, not only sparing punishment; promised reward is still a favour.', '["الطول means only sparing punishment, since it comes right after ''severe in punishment''.", "Promised reward becomes a duty on God, so it no longer counts as a favour."]', 'What الطول means', NULL, '[]', 'الطول is God''s favour: reward and blessings, or those plus sparing a punishment that was deserved. That is better than limiting it to sparing punishment, even though it comes right after ''severe in punishment''. Some argue a promised reward is like a debt, so it is not a favour. The commentator rejects this, because making the promise was not a duty in the first place.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:114-116', 'QRTA:alusi:40-01', 'alusi', 114, 116, 40, 1, 3, 'The ''and'' joining Forgiver and Accepter means the repentant sinner gets two mercies together.', '["The ''and'' joining Forgiver and Accepter means each mercy goes to a different kind of sinner.", "The ''and'' means repentance is accepted, but the sin itself stays on record."]', 'The joining و', 'وَاو العَطْف', '["GT:harf_maani:atf", "GT:irab_role:naat"]', 'Other early meanings of الطول are also listed: plenty, blessings, or power. The و between غافر الذنب and قابل التوب shows that the repentant sinner gets two mercies at once. God accepts his repentance and records it as obedience, and makes it wipe out the sin as if it never happened. So God is ''the One who joins forgiveness and acceptance''.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:117-119', 'QRTA:alusi:40-01', 'alusi', 117, 119, 40, 1, 3, 'Adjectives in a row already join; adding ''and'' to one pair marks both mercies for the repentant.', '["Adjectives in a row never join their meanings, so ''and'' is needed between every pair.", "Adding ''and'' here means God forgives only those who repent, and no one else."]', 'The joining و', 'وَاو العَطْف', '["GT:harf_maani:atf"]', 'Adjectives listed one after another without و already show they all belong together. So when و is put with just one pair, it must add something, since eloquent speech has no wasted words. Here it shows God joins forgiveness and acceptance for the one who repents in particular. This does not deny that God may also forgive someone who has not repented.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:120-121', 'QRTA:alusi:40-01', 'alusi', 120, 121, 40, 1, 3, 'A view splitting forgiveness for the unrepentant and acceptance for the repentant is not accepted.', '["A view splitting forgiveness for the repentant and acceptance for the unrepentant is accepted.", "The split view is accepted, since an early report about the ''and'' supports it."]', 'The joining و', NULL, '[]', 'Some said the و in the middle points to two separate groups: ''Forgiver of sin for the one who has not repented, and Accepter of repentance for the one who has.'' An early report is given for this. The commentator does not accept it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:122-123', 'QRTA:alusi:40-01', 'alusi', 122, 123, 40, 1, 3, 'The claimed difference between forgiving and accepting comes from the adjectives themselves, not the ''and''.', '["The claimed difference between forgiving and accepting comes only from the ''and'', not the adjectives.", "Forgiveness covers sins wiped from the record, and acceptance covers sins still on it."]', 'The joining و', 'وَاو العَطْف', '["GT:harf_maani:atf"]', 'Others say forgiveness and acceptance deal with different sins. Forgiveness covers a sin still in the record but not punished; acceptance covers a sin wiped off the record. The commentator says this difference already comes from the two adjectives themselves, so the و plays no part in it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:124-124', 'QRTA:alusi:40-01', 'alusi', 124, 124, 40, 1, 3, 'The earlier explanation fits both schools of belief, so there is no reason to reject it.', '["The earlier explanation fits only one school of belief, so it should be rejected.", "The earlier explanation is the weaker one, so the other view should be preferred."]', 'Keeping the stronger view', NULL, '[]', 'The first explanation of the و, two mercies for the one who repents, works on the basic beliefs of both أهل السنة and المعتزلة. So it should not be rejected for reasons that do not harm it. Nor should a weaker view be preferred over it.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:125-125', 'QRTA:alusi:40-01', 'alusi', 125, 125, 40, 1, 3, '''Forgiver'' comes before ''Accepter'' because clearing away faults comes before adding good.', '["''Accepter'' comes before ''Forgiver'' because adding good comes before clearing faults.", "''Forgiver'' comes first because forgiving is a greater act than accepting repentance."]', 'Word order', 'التقديم والتأخير', '["GT:balagha_maani:taqdim_takhir"]', 'Putting غافر before قابل (تقديم) follows a known order: التخلية before التحلية. First a place is emptied of what is bad, then it is decorated with what is good. So the sin is cleared first, then the repentance is accepted.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:126-126', 'QRTA:alusi:40-01', 'alusi', 126, 126, 40, 1, 3, 'On whether a sinner''s repentance is surely accepted, Sunni scholars hold two views.', '["All Sunni scholars agree that a sinner''s repentance is surely accepted.", "Sunni scholars hold two views on whether a sin can be forgiven without repentance."]', 'Is repentance surely accepted?', NULL, '[]', 'The commentator raises a question: is it certain that God accepts the repentance of a sinner? أهل السنة have two views on this.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:127-128', 'QRTA:alusi:40-01', 'alusi', 127, 128, 40, 1, 3, 'Repentance from any sin is surely accepted; one punishment name among mercy names shows mercy leads.', '["Only repentance from unbelief is surely accepted; one punishment name among mercy names shows fear leads.", "The punishment name sits among mercy names to show both carry equal weight."]', 'Mercy outweighs punishment', NULL, '[]', 'Another commentary says the plain sense of the verse is that repentance is surely accepted, whether the sin was unbelief (الكفر) or something less. Also, only one name speaks of punishment, and it is surrounded by names of mercy. That shows God''s mercy is greater and comes first.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:129-130', 'QRTA:alusi:40-01', 'alusi', 129, 130, 40, 1, 3, 'No god but Him, so full obedience is due; all return to Him alone for repayment.', '["No god but Him, so full obedience is due; all return to Him and His partners.", "All return to Him alone, but He repays only the obedient, not the disobedient."]', 'Oneness and the final return', NULL, '["GT:sentence_role:istinafiyya"]', '''There is no god but He'' means one must turn fully to obeying Him in all He commands and forbids. ''To Him is the final return'' means to Him alone, not to anyone else, either alone or as a partner. There He will repay everyone, the obedient and the disobedient.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:131-132', 'QRTA:alusi:40-01', 'alusi', 131, 132, 40, 1, 3, 'The clause ''no god but He'' is a new sentence, a حال, or an adjective.', '["The clause ''no god but He'' is the predicate of حم, or an adjective of the Book.", "The clause ''no god but He'' must be a حال; no other reading is possible."]', 'A new, independent clause', 'استئنافية', '["GT:sentence_role:hal", "GT:sentence_role:naat"]', 'The sentence لا إله إلا هو can be read three ways. It may be a new, independent sentence (مستأنفة), or a حال describing God. Or it may be an adjective (صفة) of الله, or of ''severe in punishment''. These verses hold much that calls for taking heed.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:133-135', 'QRTA:alusi:40-01', 'alusi', 133, 135, 40, 1, 3, 'The caliph missed a strong man from Syria and learned he had given himself to drink.', '["The caliph missed a strong man from Syria and learned he had gone off to war.", "A strong man from Syria missed the caliph and wrote to ask after him."]', 'A story about repentance', NULL, '[]', 'To show the lesson of these verses, the commentator tells a story. A strong, brave man from Syria stopped coming, and the caliph asked about him. He was told the man had given himself over to drink (تتابع في الشراب). So the caliph called his scribe.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:136-138', 'QRTA:alusi:40-01', 'alusi', 136, 138, 40, 1, 3, 'The caliph wrote him these opening verses and had them delivered only once he was sober.', '["The caliph wrote him a harsh warning and had it sent at once, sober or not.", "The caliph wrote him the verses and told his people to pray for his punishment."]', 'A story about repentance', NULL, '[]', 'The letter had a greeting, praise of God ''besides whom there is no god'', and then the verses from حم to ''to Him is the final return''. The caliph told the messenger not to hand it over until the man was sober. He also asked those with him to pray that the man would repent.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:139-140', 'QRTA:alusi:40-01', 'alusi', 139, 140, 40, 1, 3, 'Reading it, the man saw God''s promise of forgiveness and warning of punishment, wept, and quit.', '["Reading it, the man saw only God''s warning of punishment, grew afraid, and fled.", "Reading it, the man felt sure of forgiveness, so he saw no need to stop."]', 'Hope and fear together', NULL, '[]', 'The man kept reading the letter and saying: ''My Lord has promised to forgive me and warned me of His punishment.'' That is the hope and fear of ''Forgiver of sin, severe in punishment''. He repeated it until he wept, then gave up drinking for good.', 'live');
INSERT INTO qr_tafsir_sentence (id, audio_id, source_slug, seq_from, seq_to, surah, ayah_from, ayah_to, gist_en, wrong_json, concept_en, concept_ar, terms_json, meaning_en, status) VALUES ('tafsir_sent:QRTA:alusi:40-01:141-142', 'QRTA:alusi:40-01', 'alusi', 141, 142, 40, 1, 3, 'When a brother slips, set him right and pray for him; don''t help the devils against him.', '["When a brother slips, leave him alone so the devils do not reach you too.", "When a brother slips, shame him openly so that others will not do the same."]', 'Helping a brother who slips', NULL, '[]', 'When the caliph heard of the man''s repentance, he told the people to act the same way. If a brother slips, steady him, guide him, and pray that God turns to him. Do not become helpers of the devils against him.', 'live');
